window.POEM_DB=window.POEM_DB||{};POEM_DB["song_036"]={"n":"吴芾","dyn":"宋","poems":[{"t":"七夕戏成二绝 其一","f":"七言绝句","c":["时入三秋气已清，节临七夕露初零。","如何老子临风坐，也望天河牛女星。"]},{"t":"七夕戏成二绝 其二","f":"七言绝句","c":["寄语天河牛女星，人人乞巧望聪明。","老夫养拙生憎巧，只要冥心度此生。"]},{"t":"九月二十六日同朝宗泽民游洞宫用刘使君韵二首 其二","f":"七言绝句","c":["爱游此地已多年，今日身心始豁然。","洞里真人虽羽化，苍苍乔木自参天。"]},{"t":"九月二十六日同朝宗泽民游洞宫用刘使君韵二首 其一","f":"七言绝句","c":["云藏仙窟几何年，一旦来游岂偶然。","造物应怜林下客，故令一睹洞中天。"]},{"t":"二十七日泛舟偶成","f":"七言绝句","c":["小舟游漾小池中，偶与吾人笑语同。","好把钓竿烟雨里，一蓑放我作渔翁。"]},{"t":"入界","f":"七言绝句","c":["日炙风吹人倦乏，山重水复路萦回。","一番行病思休息，且喜今朝入界来。"]},{"t":"十五夜南园纳凉","f":"七言绝句","c":["兀坐铃斋困郁蒸，举头忽见月华明。","兴来策杖园中去，聊复寻山听水声。"]},{"t":"十六夜见月","f":"七言绝句","c":["连宵待月屡登城，特地遮藏不肯明。","过了佳辰方皎洁，嫦娥何事太无情。"]},{"t":"又和黄清表惠早梅","f":"七言绝句","c":["姑射风姿绝点埃，年年长是腊前开。","方疑今岁无消息，多谢君能折取来。"]},{"t":"又登碧云亭感怀三十首 其三十","f":"七言绝句","c":["晚上危亭喜有秋，民安物阜本无忧。","铃斋坐啸虽多暇，争似归田得自由。"]},{"t":"又登碧云亭感怀三十首 其二十九","f":"七言绝句","c":["晚上危亭懒举头，竹椽芦屋亦堪羞。","我将一变成雄观，长与邦人作宴游。"]},{"t":"又登碧云亭感怀三十首 其二十八","f":"七言绝句","c":["晚上危亭忆隐居，高情逸气古人无。","横山祇有精庐在，无复书堂旧药炉。"]},{"t":"又登碧云亭感怀三十首 其二十七","f":"七言绝句","c":["晚上危亭忆令威，凌虚山上悟玄机。","丹成不见升腾迹，徒想当年化鹤飞。"]},{"t":"又登碧云亭感怀三十首 其二十六","f":"七言绝句","c":["晚上危亭忆孟君，龙山一醉见天真。","堪嗟东道空遗臭，争似尊前落帽人。"]},{"t":"又登碧云亭感怀三十首 其二十五","f":"七言绝句","c":["晚上危亭望石城，楚君曾向此间兴。","城池芜没人何在，只有空山几个僧。"]},{"t":"又登碧云亭感怀三十首 其二十四","f":"七言绝句","c":["晚上危亭想谪仙，孤坟寂寂锁寒烟。","高风直节谁能继，只有诗篇后代传。"]},{"t":"又登碧云亭感怀三十首 其二十三","f":"七言绝句","c":["晚上危亭一凭栏，青青最爱谢家山。","谢公陈迹虽磨灭，馀韵遗风尚可攀。"]},{"t":"又登碧云亭感怀三十首 其二十二","f":"七言绝句","c":["晚上危亭景色饶，眼中突兀是凌歊。","三千粉黛知何许，祇有江山锁寂寥。"]},{"t":"又登碧云亭感怀三十首 其二十一","f":"七言绝句","c":["晚上危亭望大江，天教千古作金汤。","中流击楫人何在，徒感兴亡对夕阳。"]},{"t":"又登碧云亭感怀三十首 其二十","f":"七言绝句","c":["晚上危亭与客同，话头只是说山中。","老来百念消磨尽，只有归心羡暮鸿。"]},{"t":"又登碧云亭感怀三十首 其十九","f":"七言绝句","c":["晚上危亭力已疲，胡为归计尚迟迟。","如今若便休官去，也胜当初未有时。"]},{"t":"又登碧云亭感怀三十首 其十八","f":"七言绝句","c":["晚上危亭为少留，亭前暝色已供愁。","更听画角声悲壮，愈使愁人厌远游。"]},{"t":"又登碧云亭感怀三十首 其十七","f":"七言绝句","c":["晚上危亭待月生，云头俄涌一轮明。","终朝汩没尘埃里，对此身心觉顿清。"]},{"t":"又登碧云亭感怀三十首 其十六","f":"七言绝句","c":["晚上危亭避郁蒸，风生两腋觉身轻。","更筹只是催归去，不到城头月未生。"]},{"t":"又登碧云亭感怀三十首 其十五","f":"七言绝句","c":["晚上危亭览物华，斜阳影里度归鸦。","暮山隔断乡关路，矫首临风眼欲花。"]},{"t":"又登碧云亭感怀三十首 其十四","f":"七言绝句","c":["晚上危亭望远山，望中有水亦回环。","终然不似吾庐好，上下山光水色间。"]},{"t":"又登碧云亭感怀三十首 其十三","f":"七言绝句","c":["晚上危亭咏式微，封章再上未容归。","羡他白鹭凌风去，却向山前自在飞。"]},{"t":"又登碧云亭感怀三十首 其十二","f":"七言绝句","c":["晚上危亭望彼苍，时时飞电迸流光。","嗟人生世须臾里，未必能如电久长。"]},{"t":"又登碧云亭感怀三十首 其十一","f":"七言绝句","c":["晚上危亭顾四隅，小松环绕几千株。","他年黛色侵天去，应记栽时是老夫。"]},{"t":"又登碧云亭感怀三十首 其十","f":"七言绝句","c":["晚上危亭指顾间，羊牛来下鸟飞还。","细思物理须知止，何用区区祇强颜。"]},{"t":"又登碧云亭感怀三十首 其九","f":"七言绝句","c":["晚上危亭一解颜，公馀偷得半时闲。","未能投绂寻归路，聊复衔杯对好山。"]},{"t":"又登碧云亭感怀三十首 其八","f":"七言绝句","c":["晚上危亭兴未穷，仰看星斗已悬空。","可怜熠耀飞撩乱，也欲争光迥野中。"]},{"t":"又登碧云亭感怀三十首 其七","f":"七言绝句","c":["晚上危亭侧耳听，新蝉噪罢乱蛙鸣。","老来只是便幽静，颇厌人间强聒声。"]},{"t":"又登碧云亭感怀三十首 其六","f":"七言绝句","c":["晚上危亭逸兴多，却寻小艇下烟波。","酒狂聊作碧筒饮，折尽花间几柄荷。"]},{"t":"又登碧云亭感怀三十首 其五","f":"七言绝句","c":["晚上危亭看绿荷，风翻荷叶欲藏花。","使君要见红妆面，莫放碧云重叠遮。"]},{"t":"又登碧云亭感怀三十首 其四","f":"七言绝句","c":["晚上危亭瞰野塘，藕花无数散清香。","若为荷叶分青绿，一半红妆半淡妆。"]},{"t":"又登碧云亭感怀三十首 其三","f":"七言绝句","c":["晚上危亭喜作晴，亦思郊外一闲行。","无端骑从相遮护，不放山翁适野情。"]},{"t":"又登碧云亭感怀三十首 其二","f":"七言绝句","c":["晚上危亭眼暂明，风烟浓淡媚郊坰。","个中妙处吟难尽，分付人间作画屏。"]},{"t":"又登碧云亭感怀三十首 其一","f":"七言绝句","c":["晚上危亭暑气清，薰风微动入疏棂。","重重草树高低绿，叠叠峰峦远近青。"]},{"t":"三七侄入新屋 其二","f":"七言绝句","c":["我昔行年近六旬，辛勤才有屋容身。","汝成广厦年方壮，端是吾家有福人。"]},{"t":"三七侄入新屋 其一","f":"七言绝句","c":["华屋新成集贺宾，门阑盛事一番新。","愿言积德高于屋，屋下长存百岁人。"]},{"t":"三三径","f":"七言绝句","c":["种成松竹与江梅，杖履相过日几回。","莫谓个中三友足，也须更许老夫来。"]},{"t":"上七斋素不饮","f":"七言绝句","c":["人日晴天万里开，自应一笑上春台。","清斋偶阻花前醉，且把茶瓯当酒杯。"]},{"t":"久拟重阳一登龙山以荒榛峭壁无容足之地欲访昔人风帽遗址竟不可得遂领客之凌歊偶成四绝 其四","f":"七言绝句","c":["宦情一似秋容薄，归兴浑如酒味浓。","台上望乡何处是，夕阳影里暮山重。"]},{"t":"久拟重阳一登龙山以荒榛峭壁无容足之地欲访昔人风帽遗址竟不可得遂领客之凌歊偶成四绝 其一","f":"七言绝句","c":["登高自古说龙山，拟访遗踪去路难。","赖有凌歊台尚在，不妨怀古凭栏干。"]},{"t":"久拟重阳一登龙山以荒榛峭壁无容足之地欲访昔人风帽遗址竟不可得遂领客之凌歊偶成四绝 其三","f":"七言绝句","c":["下车日日欲登台，直到重阳始一来。","好对江山拚酩酊，此怀能得几时开。"]},{"t":"久拟重阳一登龙山以荒榛峭壁无容足之地欲访昔人风帽遗址竟不可得遂领客之凌歊偶成四绝 其二","f":"七言绝句","c":["当年宋武筑凌歊，人去台空气尚豪。","欲吊兴亡无处问，且凭茱菊荐芳醪。"]},{"t":"久欲乞归未得一日蒙恩放归不胜欣喜涂中得十五首 其十五","f":"七言绝句","c":["淡烟斜日媚郊原，中有人家似辋川。","地侧忽惊车马过，三三两两竹篱边。"]},{"t":"久欲乞归未得一日蒙恩放归不胜欣喜涂中得十五首 其十四","f":"七言绝句","c":["兀兀篮舆足欲拳，聊扶藜杖步山边。","招提此去无多地，且就僧房借榻眠。"]},{"t":"久欲乞归未得一日蒙恩放归不胜欣喜涂中得十五首 其十三","f":"七言绝句","c":["路傍遥见一山居，欢喜犹如见故庐。","见似故庐犹自喜，如今到后喜何如。"]},{"t":"久欲乞归未得一日蒙恩放归不胜欣喜涂中得十五首 其十二","f":"七言绝句","c":["荒墟忽见翠成堆，错认青山入眼来。","元是松林如此好，不妨归去更勤栽。"]},{"t":"久欲乞归未得一日蒙恩放归不胜欣喜涂中得十五首 其十一","f":"七言绝句","c":["无日无时不念归，此心宜有鬼神知。","如今已作终焉计，寄语山灵莫勒移。"]},{"t":"久欲乞归未得一日蒙恩放归不胜欣喜涂中得十五首 其十","f":"七言绝句","c":["欲寒还暖雨还晴，极目秋郊景色明。","应是此归天亦喜，故将风日作人情。"]},{"t":"久欲乞归未得一日蒙恩放归不胜欣喜涂中得十五首 其九","f":"七言绝句","c":["夹道乔松几度春，青青黛色四时新。","当时若尽荒郊种，万顷清阴更可人。"]},{"t":"久欲乞归未得一日蒙恩放归不胜欣喜涂中得十五首 其八","f":"七言绝句","c":["记得年时入境来，老分阃寄惧非才。","今朝遂出洪都去，笑指故山真快哉。"]},{"t":"久欲乞归未得一日蒙恩放归不胜欣喜涂中得十五首 其七","f":"七言绝句","c":["去年来见荷初败，今岁归逢菊已残。","残菊败荷浑似我，纵馀芬馥岂堪观。"]},{"t":"久欲乞归未得一日蒙恩放归不胜欣喜涂中得十五首 其六","f":"七言绝句","c":["邦人送我说殷勤，自愧初无德及民。","若更踌躇不归去，猿惊鹤怨亦愁人。"]},{"t":"久欲乞归未得一日蒙恩放归不胜欣喜涂中得十五首 其五","f":"七言绝句","c":["老夫非是厌洪都，正恐沉迷失故吾。","纵使东湖花似锦，不如归对小西湖。"]},{"t":"久欲乞归未得一日蒙恩放归不胜欣喜涂中得十五首 其四","f":"七言绝句","c":["来时似觉秋犹热，去日忽惊秋已深。","一去一来何所益，不如归去旧园林。"]},{"t":"久欲乞归未得一日蒙恩放归不胜欣喜涂中得十五首 其三","f":"七言绝句","c":["东去匆匆不暂停，我于此地岂无情。","祇缘衰病归心切，不惮崎岖趁晓程。"]},{"t":"久欲乞归未得一日蒙恩放归不胜欣喜涂中得十五首 其二","f":"七言绝句","c":["我病只宜投绂去，君恩却许奉祠归。","小人报国非无志，正恐叨踰触祸机。"]},{"t":"久欲乞归未得一日蒙恩放归不胜欣喜涂中得十五首 其一","f":"七言绝句","c":["今日方行第一程，看来已觉此身轻。","若还归到湖山里，何啻乘云上玉清。"]},{"t":"子肃见示和篇复次韵","f":"七言绝句","c":["花到浓时自有香，未逢真赏亦堪伤。","今朝渗鼻浑如许，岂是兹花返故常。"]},{"t":"小有洞","f":"五言绝句","c":["世人竞蜗角，终日汩尘缘。","谁谓名园内，深藏小洞天。"]},{"t":"山居上元","f":"七言绝句","c":["未能免俗强随缘，聊挂灯毬记上元。","席上虽无罗绮绕，游人来往亦喧喧。"]},{"t":"予赴官当涂绝江而西夜宿慈严秉烛游三洞时主僧出示诸公留题因用乐天韵成一绝","f":"七言绝句","c":["洞中风水锁松筠，一见都忘老病身。","安得结茅长此住，临风临水作闲人。"]},{"t":"云龛","f":"七言绝句","c":["君将富贵等浮云，却许白云来就宿。","静处何妨共一龛，免教随手翻还复。"]},{"t":"五月七日晚登碧云亭有感","f":"七言绝句","c":["连岁芙蕖照眼明，今年荷叶又青青。","老夫去此无他恋，祇忆看花水上亭。"]},{"t":"今日春色可佳乘兴谒许倅因成小诗","f":"七言绝句","c":["春入风流别乘家，满园桃李掞春华。","殷勤为我倾醇酎，要看庭前百树花。"]},{"t":"元夕即席呈郭次张","f":"七言绝句","c":["过了元宵到晓钟，一年乐事又成空。","杯行不用深辞醉，明日君西我亦东。"]},{"t":"六月二十一日早行十六首 其十六","f":"七言绝句","c":["暂归祇欲见湖山，多谢亲朋日往还。","但愧年衰筋骨惫，将迎容我片时閒。"]},{"t":"六月二十一日早行十六首 其十五","f":"七言绝句","c":["只爱湖光似镜平，那知汹涌作潮鸣。","直疑身在江船上，夜半更闻风雨声。"]},{"t":"六月二十一日早行十六首 其十四","f":"七言绝句","c":["谩来水上结危亭，更凭栏干听水声。","洗得肺肝清似水，莫言亭下水无情。"]},{"t":"六月二十一日早行十六首 其十三","f":"七言绝句","c":["竹间幽径喜相通，花下清阴苦未浓。","说与园丁勤灌溉，我归要此养疏慵。"]},{"t":"六月二十一日早行十六首 其十二","f":"七言绝句","c":["不见湖山两阅冬，相思千里梦魂通。","今宵烛下匆匆看，犹恐归来似梦中。"]},{"t":"六月二十一日早行十六首 其十一","f":"七言绝句","c":["出入乡关四十期，劳人迎送每惭之。","今朝单骑归来速，且喜乡人都不知。"]},{"t":"六月二十一日早行十六首 其十","f":"七言绝句","c":["东望吾庐百里间，二年别去一朝还。","虽然未遂归休意，且对湖山一解颜。"]},{"t":"六月二十一日早行十六首 其九","f":"七言绝句","c":["蝉噪园林处处同，此蝉鸣处颤春风。","祇应寒饿全无力，吟不成声喙已穷。"]},{"t":"六月二十一日早行十六首 其八","f":"七言绝句","c":["篮舆亟欲到柴门，终日驱驰亦苦辛。","野外莫嫌车骑少，笙歌两部自随人。"]},{"t":"六月二十一日早行十六首 其七","f":"七言绝句","c":["古寺经行知几回，山僧又见我重来。","暮年欲作终焉计，不得归休只自哀。"]},{"t":"六月二十一日早行十六首 其六","f":"七言绝句","c":["雨后西山气象新，野田高下水津津。","晚来弛担临风坐，聒耳蛙声更可人。"]},{"t":"六月二十一日早行十六首 其五","f":"七言绝句","c":["欲挂衣冠已上章，更令冲冒去南昌。","南昌纵有佳山水，争似安閒在故乡。"]},{"t":"六月二十一日早行十六首 其四","f":"七言绝句","c":["为忆湖山且暂归，此心不是要追时。","君恩留我非由己，寄语山灵莫勒移。"]},{"t":"六月二十一日早行十六首 其三","f":"七言绝句","c":["病躯终日困骄阳，正虑行行去路长。","多谢天公怜此意，时飞疏雨作清凉。"]},{"t":"六月二十一日早行十六首 其二","f":"七言绝句","c":["稻苗初穗出纷纷，半是青云半白云。","坐看黄云呈上瑞，田家无处不忻忻。"]},{"t":"六月二十一日早行十六首 其一","f":"七言绝句","c":["四更山月吐微明，起促篮舆趁早行。","忽听疾雷催雨急，风生襟袖不胜清。"]},{"t":"六月末间拒霜已开","f":"五言绝句","c":["暑气犹未退，寒花早已开。","衰年宁有几，寒暑若相催。"]},{"t":"月岩","f":"七言绝句","c":["半轮斜月挂岩边，见者多应叹未圆。","圆极会如钩样曲，何如此月镇婵娟。"]},{"t":"月沼","f":"七言绝句","c":["大道从来恶满盈，脱身便欲老岩扃。","杜门渐解埋光意，积水姑为半月形。"]},{"t":"东湖观荷有感 其一","f":"七言绝句","c":["自有东湖知几年，荷花今日尚依然。","堪嗟世事时时改，祇有荷花岁岁妍。"]},{"t":"东湖观荷有感 其二","f":"七言绝句","c":["双头并蒂出天然，呈瑞悬知好事连。","果得故人来对饮，何妨一笑到金莲。"]},{"t":"东楼落成二绝 其二","f":"七言绝句","c":["人道楼前碍瓮城，无多山色到檐楹。","那知皂盖行春日，却与春风最有情。"]},{"t":"东楼落成二绝 其一","f":"七言绝句","c":["荒郡城楼久已倾，我来聊复为经营。","南楼已是增雄观，今日东楼又落成。"]},{"t":"代张发答","f":"七言绝句","c":["天作凶荒可奈何，饱人渐少饿人多。","小人已免饥寒迫，纵得钱多待怎么。"]},{"t":"北楼二首 其二","f":"七言绝句","c":["折冲自古在精神，从事兵车亦苦辛。","羽扇纶巾前日事，尚能谈笑静风尘。"]},{"t":"北楼二首 其一","f":"七言绝句","c":["不分群儿敢跳梁，向来走马饮长江。","兹楼不是为观美，要向楼前受敌降。"]},{"t":"去春劝耕云际移植海棠曾留小诗今岁困于多事欲往不果怅然有怀复和前韵以示主僧","f":"七言绝句","c":["去年劝相到云根，满树花光欲照人。","料得今年花更好，无端风雨阻行春。"]},{"t":"去郡登舟偶成一绝","f":"七言绝句","c":["脱得身来上短篷，飘然初试一帆风。","孤城回首知何处，祇有凌歊在眼中。"]},{"t":"四月二十一日同妻孥泛舟登吕氏济川亭二首 其二","f":"七言绝句","c":["吕公清德著吾乡，生爱兹山死便藏。","顾我来游虽恨晚，尚思杖屦共徜徉。"]},{"t":"四月二十一日同妻孥泛舟登吕氏济川亭二首 其一","f":"七言绝句","c":["不到兹山二十秋，重来山水更清幽。","无因得向岩前住，日日持竿上钓舟。"]},{"t":"归自郡中道上口占","f":"七言绝句","c":["禾黍离离压道旁，蹇驴归去晚风凉。","扬鞭西指吾庐近，想见新醅已可尝。"]},{"t":"戊子孟夏二十二日登碧云亭有感二首 其二","f":"七言绝句","c":["来时荷盖翠相扶，不谓经年尚守株。","纵使香风来不断，争如归去小西湖。"]},{"t":"戊子孟夏二十二日登碧云亭有感二首 其一","f":"七言绝句","c":["去年昨日我离家，转眼俄惊阅岁华。","春草池塘长入梦，不堪两度见荷花。"]},{"t":"戊子春术者刘五星谓予寿有八十一感而有作二首 其二","f":"七言绝句","c":["多少同年尽溘然，我今独喜尚安全。","傥延朝夕诚为幸，敢谓犹能十五年。"]},{"t":"戊子春术者刘五星谓予寿有八十一感而有作二首 其一","f":"七言绝句","c":["纵使诚如日者言，此身只合在林泉。","从今便得休官去，止有闲居十五年。"]},{"t":"玉山道中","f":"七言绝句","c":["路绕孤村一径微，上连碧嶂下清溪。","水光山色浑如画，引得行人忆故栖。"]},{"t":"生朝有感","f":"五言绝句","c":["每岁逢生日，予心喜复悲。","新年六十六，能得几多时。"]},{"t":"甲子日无雨偶成","f":"七言绝句","c":["连岁人怀水潦忧，年登犹叹不全收。","夏逢甲子天无雨，预喜今年又有秋。"]},{"t":"会贾守邀许倅有感 其一","f":"七言绝句","c":["当年婺女三人别，今日姑溪一席同。","老去光阴能有几，相逢莫放酒杯空。"]},{"t":"会贾守邀许倅有感 其二","f":"七言绝句","c":["宿雾浓云拨不开，更倾骤雨下天来。","天公也喜人欢聚，故遣斜阳送一杯。"]},{"t":"再见双头莲","f":"七言绝句","c":["我来才见月初圆，两度池开并蒂莲。","嘉瑞还来非偶尔，悬知连岁有丰年。"]},{"t":"再用示方山人韵二首 其二","f":"七言绝句","c":["不羡千金狐腋裘，只知饱暖度春秋。","如今万事皆踰分，此外何求更不休。"]},{"t":"再用示方山人韵二首 其一","f":"七言绝句","c":["暮年不是苦思归，已约湖山恐失期。","此意有谁能会得，祇应猿鹤是相知。"]},{"t":"再和","f":"七言绝句","c":["诸公得得走车轮，要向忙中乐此身。","我昔不来今日到，始知枉作把麾人。"]},{"t":"再和","f":"七言绝句","c":["坐上花光欲照人，深疑花是洛中神。","已拚今日如泥醉，何必须分妄与真。"]},{"t":"再和天予二首 其二","f":"七言绝句","c":["中秋花月共徘徊，正喜相逢笑口开。","君既不留吾亦去，何时又向此间来。"]},{"t":"再和天予二首 其一","f":"七言绝句","c":["行轩未用苦相催，花下清尊正欲开。","君若此时留不住，何如当日罢休来。"]},{"t":"再和绝句寄韩子云","f":"七言绝句","c":["开尽千花到藕花，相将又听采莲歌。","无人共酌樽中醁，奈此花前风月何。"]},{"t":"后圃初见梅花一萼二首 其二","f":"七言绝句","c":["枝头已是送春来，怀抱何妨试割开。","满园若欲俱开遍，须倩杯觞日日催。"]},{"t":"后圃初见梅花一萼二首 其一","f":"七言绝句","c":["杖藜閒步小园来，喜见寒梅一萼开。","若无春意犹羞涩，应待诗翁着句催。"]},{"t":"如老堂 其二","f":"七言绝句","c":["一堂风月一床书，随分琴樽乐有馀。","试问乘轩遮道客，何如归去狎樵渔。"]},{"t":"如老堂 其一","f":"七言绝句","c":["少年有志觅封侯，老去知非万事休。","薄有田园能自适，不妨卖剑买黄牛。"]},{"t":"安仁绝览亭","f":"七言绝句","c":["檐前列岫连云耸，亭下双溪彻底清。","可但坐来无暑气，老夫病眼顿增明。"]},{"t":"安仁挹仙亭","f":"七言绝句","c":["区区终日困尘劳，长恨仙山去路遥。","岂谓一朝供顾挹，坐令逸气出层霄。"]},{"t":"扫坟东山感旧示十五侄","f":"七言绝句","c":["四十年前此读书，与君俱欲上亨衢。","君虽未达心犹壮，我已衰颓作老夫。"]},{"t":"早行五首 其五","f":"七言绝句","c":["我无政术强为官，所至将迎每厚颜。","何事深村赤脚妇，亦闻钲鼓出篱间。"]},{"t":"早行五首 其四","f":"七言绝句","c":["跋涉州涂仅八旬，今朝才得次安仁。","更须五日为行客，方得开藩见吏民。"]},{"t":"早行五首 其三","f":"七言绝句","c":["长涂终日困炎蒸，破晓扶衰强趁程。","好是篮舆桥上过，一钩斜月水中明。"]},{"t":"早行五首 其二","f":"七言绝句","c":["此地惟多古树林，路傍处处足清阴。","行人九夏热如火，到此清风忽满襟。"]},{"t":"早行五首 其一","f":"七言绝句","c":["畏暑凌晨更疾驱，疏星影里度篮舆。","忽惊道上人如堵，知是田家出趁墟。"]},{"t":"有感十首 其十","f":"七言绝句","c":["宫院深深今是非，可无三户报秦期。","直应更作包胥泣，未抵含冤屈宋词。"]},{"t":"有感十首 其九","f":"七言绝句","c":["漠漠黄云塞草低，南人空说翠舆归。","孤臣泪尽仍尝胆，白首江湖雁北飞。"]},{"t":"有感十首 其八","f":"七言绝句","c":["河山关塞一万里，文武衣冠二百年。","四海萧条宫殿去，无人解道取幽燕。"]},{"t":"有感十首 其七","f":"七言绝句","c":["雪压穹庐风怒号，纷然羊马杂腥臊。","遥知玉座无馀地，叹息功臣甲第高。"]},{"t":"有感十首 其六","f":"七言绝句","c":["蜀锦机中瑞鹘盘，宫袍岁岁给千官。","朱门次第皆轻暖，御所空悲易水寒。"]},{"t":"有感十首 其五","f":"七言绝句","c":["草芥萧然十阁珍，车中妆具不时新。","留犁服匿谁供给，台阁悠悠食肉人。"]},{"t":"有感十首 其四","f":"七言绝句","c":["塞曲咿呜催断肠，毡车轣辘载啼妆。","汉家近属三千客，性命如丝寄虎狼。"]},{"t":"有感十首 其三","f":"七言绝句","c":["洛邑尘氛暗不开，百年宫殿总成灰。","柏城昼日风萧瑟，不见朝陵敕使来。"]},{"t":"有感十首 其二","f":"七言绝句","c":["延福池台荆棘深，上皇无复更登临。","寂寥崇观当年事，愁绝关河万里心。"]},{"t":"有感十首 其一","f":"七言绝句","c":["当年旧迹已尘埃，晓日犹疑讲殿开。","涕泪不知黄屋处，伤心时有北人回。"]},{"t":"竹坞","f":"七言绝句","c":["此君生长此山中，直节从来自不同。","今日高标还卓出，万人谁不仰清风。"]},{"t":"西安道中二首 其二","f":"七言绝句","c":["水浸野苗森碧玉，风翻早稻卧黄云。","有年如许诚希见，农父犹言未十分。"]},{"t":"西安道中二首 其一","f":"七言绝句","c":["平林环翠如山立，野水涵空似镜开。","道上人家多美竹，欲行未去更徘徊。"]},{"t":"观十二弟种德堂诗和其韵","f":"七言绝句","c":["万事忘怀付酒樽，长閒不厌客登门。","但存心地平如砥，胜买黄牛教子孙。"]},{"t":"许倅索和篇复次前韵","f":"七言绝句","c":["十分春色在邻家，我独伤心感物华。","君若此时辞痛饮，也应辜负后园花。"]},{"t":"过上饶有感","f":"七言绝句","c":["少日随亲官此州，如今老矣复来游。","此身纵健那能久，何苦奔驰不自休。"]},{"t":"过许氏居","f":"七言绝句","c":["山崖水畔得幽居，一见令人忆故庐。","幸有山围并水绕，天胡不放我归欤。"]},{"t":"过姑苏","f":"七言绝句","c":["游宦重来二十年，江山风物总依然。","道傍民吏犹相记，独怪吾衰雪满颠。"]},{"t":"过金陵","f":"七言绝句","c":["当时护跸此盘旋，倒指重来仅十年。","决策迁都言漫切，自怜微力莫回天。"]},{"t":"过嘉禾呈方懋德","f":"七言绝句","c":["昔尝此地奉周旋，倒指于今三十年。","今日相逢成二老，那知又复到樽前。"]},{"t":"邦人献芍药四种曰御爱红曰霓裳红曰缀珠冠子曰红都胜因同朝宗夜饮赏之遂成二绝以记一时之胜 其二","f":"七言绝句","c":["芍药移来傍玉栏，浅深浓淡一般般。","夜深促席来相就，要把春容子细看。"]},{"t":"邦人献芍药四种曰御爱红曰霓裳红曰缀珠冠子曰红都胜因同朝宗夜饮赏之遂成二绝以记一时之胜 其一","f":"七言绝句","c":["冠子缀珠初泣露，霓裳舞袖更萦风。","就中纵有红都胜，淡伫争如御爱红。"]},{"t":"伯洪以铁拄杖见寄二绝谢之 其二","f":"七言绝句","c":["铁杖君家收几年，更原古意赋成篇。","寄来岂为资扶策，应见予心老益坚。"]},{"t":"何彦清梅诗二绝用韵颇严诸公相率同和 其二","f":"七言绝句","c":["只把南枝作雪看，一般风韵照人寒。","当年儿女还知此，定借君来答谢安。"]},{"t":"何彦清梅诗二绝用韵颇严诸公相率同和 其一","f":"七言绝句","c":["清愁幽恨不禁春，寂寞池塘雪意昏。","寄语高楼莫吹笛，夜寒留取伴龙孙。"]},{"t":"余壬戌春校试进士同事者五十五人至戊子岁因阅小录所存者止四人感而有作二首 其二","f":"七言绝句","c":["只存我与二三公，可叹人生瞬息中。","纵使老来身未死，知能几度见春风。"]},{"t":"余壬戌春校试进士同事者五十五人至戊子岁因阅小录所存者止四人感而有作二首 其一","f":"七言绝句","c":["校试群才一日中，当时五十五人同。","二十七年零落尽，只存我与二三公。"]},{"t":"初至豫章二首 其二","f":"七言绝句","c":["邦人知我入城闉，夹道焚香喜色新。","愧我倦游灰百念，顾将何以慰斯人。"]},{"t":"初至豫章二首 其一","f":"七言绝句","c":["邦人喜见我之官，叠足骈肩陇亩间。","莫道使君来已暮，使君知是爱求闲。"]},{"t":"折梅","f":"七言绝句","c":["不傍茅檐便竹篱，初开犹未许人知。","一枝到手春虽浅，肯负花前金屈卮。"]},{"t":"芙蓉","f":"五言绝句","c":["谁向澄波上，尽将云锦铺。","无因一寓目，却忆小西湖。"]},{"t":"芳洲","f":"五言绝句","c":["秋风彫兰芷，芳洲久寂寞。","痛饮读离骚，此兴亦不恶。"]},{"t":"言老自云堂携十六大士画像见过与世间传写者不同惊喜赞叹因成二偈 其二","f":"七言绝句","c":["水旱无忧不用祈，祇祈心事莫相违。","我今衰老浑如许，惟仗神通放取归。"]},{"t":"言老自云堂携十六大士画像见过与世间传写者不同惊喜赞叹因成二偈 其一","f":"七言绝句","c":["禅月定中观妙相，神奇古怪乃如斯。","起来援笔一挥扫，惊杀人间老画师。"]},{"t":"陈子厚送韶鸭将以七绝因次其韵 其四","f":"七言绝句","c":["朝朝两两下平沙，添得湖中景趣嘉。","碧卵从今生育去，便堪装点作渔家。"]},{"t":"陈子厚送韶鸭将以七绝因次其韵 其三","f":"七言绝句","c":["湖光深处恣沉浮，未让波间鹭与鸥。","旧侣此时应羡汝，欲来相就苦无由。"]},{"t":"陈子厚送韶鸭将以七绝因次其韵 其六","f":"七言绝句","c":["初来便自与人宜，相近相亲自在飞。","底事悠然无畏忌，也知老子久忘机。"]},{"t":"陈子厚送韶鸭将以七绝因次其韵 其一","f":"七言绝句","c":["久闻韶鸭有灵踪，首尾俱轻快御风。","公独惠然持见赠，应知野性与余同。"]},{"t":"陈子厚送韶鸭将以七绝因次其韵 其二","f":"七言绝句","c":["兴在江湖万里间，洿池一曲岂能安。","今朝来我西湖上，眼底陡惊天地宽。"]},{"t":"陈子厚送韶鸭将以七绝因次其韵 其七","f":"七言绝句","c":["虽是微禽亦美观，岂无缯弋欲相干。","不须更起高飞念，且向湖中戢羽翰。"]},{"t":"饭客看鹤赏梅遇雨有作","f":"七言绝句","c":["鹤舞梅开总有情，小园方喜得双清。","无端风雨妨游览，不使衰翁眼暂明。"]},{"t":"到仪真沙河阻风三首 其三","f":"七言绝句","c":["连日狂风已作难，今朝浊浪更如山。","江神坚我归田志，故示危机一水间。"]},{"t":"到仪真沙河阻风三首 其二","f":"七言绝句","c":["求退那知却冒迁，天心人意古难全。","今朝行役还堪笑，下水船为上水船。"]},{"t":"到仪真沙河阻风三首 其一","f":"七言绝句","c":["快意由来未易逢，顺流却值打头风。","篙师知是江神怒，引棹重回小浦中。"]},{"t":"周相士谓予寿至九十三又成一绝","f":"七言绝句","c":["年登九九已云多，相士犹添十载过。","万事都捐无复念，老而不死待如何。"]},{"t":"和十二弟梅花","f":"七言绝句","c":["春到衡门苦恨迟，遍寻竹外赏南枝。","夜来已报春消息，试问主人知不知。"]},{"t":"和子仪送箭笋二首 其二","f":"七言绝句","c":["满合圆如玉箸匀，一开喜气顿生春。","非君与我谁知味，俗客惟誇嗜八珍。"]},{"t":"和子仪送箭笋二首 其一","f":"七言绝句","c":["与君林下久相从，蔬笋由来嗜好同。","不饷腥膻惟饷此，想应知我旧家风。"]},{"t":"和天予二首 其二","f":"七言绝句","c":["吾子才如千里驹，肯同泛泛水中凫。","乘时早取封侯印，莫惮郊原骨已枯。"]},{"t":"和天予二首 其一","f":"七言绝句","c":["自昔常难四者并，一杯相属意非轻。","祇今欲破愁城去，赖子时来举酒兵。"]},{"t":"和王知府惠双井茶","f":"七言绝句","c":["摘从双井尚馀香，远寄山翁见未尝。","咀嚼新芽味新句，陡惊冰雪沃枯肠。"]},{"t":"和王知府惠瓦砚","f":"七言绝句","c":["文房四子旧周旋，老去情疏祇自怜。","不谓陶泓犹见念，远来相顾不相捐。"]},{"t":"和任宰元绍见寄十首以归来问信湖山抚摩松菊为韵 其二","f":"五言绝句","c":["绿鬓久垂雪，壮心今已灰。","翩然归旧隐，端似再生来。"]},{"t":"和任宰元绍见寄十首以归来问信湖山抚摩松菊为韵 其八","f":"五言绝句","c":["人心生剑戟，世路足风波。","祇有归田好，谁能自揣摩。"]},{"t":"和任宰元绍见寄十首以归来问信湖山抚摩松菊为韵 其五","f":"五言绝句","c":["四围山绕舍，一带水平湖。","远近俱堪画，登临自足娱。"]},{"t":"和任宰元绍见寄十首以归来问信湖山抚摩松菊为韵 其七","f":"五言绝句","c":["闲穿脩竹行，时把孤松抚。","身世两相忘，恍如居洞府。"]},{"t":"和任宰元绍见寄十首以归来问信湖山抚摩松菊为韵 其一","f":"五言绝句","c":["出仕惭无补，长年咏式微。","天公怜我意，一旦许来归。"]},{"t":"和任宰元绍见寄十首以归来问信湖山抚摩松菊为韵 其六","f":"五言绝句","c":["开门无一事，终日饱看山。","石罅鸣流水，翻惊响佩环。"]},{"t":"和任路分喜雨","f":"七言绝句","c":["一雨欢声已沸传，更观佳句倍欣然。","一时果遂为霖望，会见重书大有年。"]},{"t":"和刘与仁见寄","f":"七言绝句","c":["莫为穷愁赋七歌，会须终日饮无何。","人间佳士由来少，世上浮名未足多。"]},{"t":"和刘与权韵三首 其三","f":"七言绝句","c":["异县相望两驿间，何时复此共看山。","向来同社今无几，莫惜篮舆数往还。"]},{"t":"和刘与权韵三首 其二","f":"七言绝句","c":["去年君过我山中，尊酒相欢十日同。","别后相思肠欲断，暮云空复指江东。"]},{"t":"和刘与权韵三首 其一","f":"七言绝句","c":["平生嗜好唯爱山，前身疑是山中相。","归来深处得幽栖，柴门正与山相向。"]},{"t":"和许守松阴","f":"七言绝句","c":["乔松转日影斜斜，穿入疏棂细作花。","怪得清阴长不改，原来松下蛰龟蛇。"]},{"t":"和许守游春 其三","f":"七言绝句","c":["尊前莫惜千金费，醉里能令万事轻。","须信人生行乐耳，此身何用绊浮名。"]},{"t":"和许守游春 其一","f":"七言绝句","c":["玉蕊琼葩压众芳，一时纵赏拥如墙。","花边笑索银瓶酒，知是谁家白面郎。"]},{"t":"和许守游春 其二","f":"七言绝句","c":["结客行行入翠微，桃源深处醉芳菲。","狂歌不减刘公干，尽日花间坐不归。"]},{"t":"和李民载梅花二首 其二","f":"七言绝句","c":["独坐无聊感岁华，骚人忽寄一枝花。","虽无素手簪罗髻，已觉春生野老家。"]},{"t":"和李民载梅花二首 其一","f":"七言绝句","c":["褐衣怀玉未全贫，况有梅花作好春。","丽句与花相映发，总输天上谪仙人。"]},{"t":"和远老四首 其四","f":"七言绝句","c":["相逢正好共看山，底事匆匆便欲还。","今日乍晴山更好，可能伴我片时閒。"]},{"t":"和远老四首 其三","f":"七言绝句","c":["世人老去不知休，祇羡三公与五侯。","争似山僧都不会，困来衲被便蒙头。"]},{"t":"和远老四首 其二","f":"七言绝句","c":["身居仕路梦家山，一日君恩放我还。","从此便为终老计，祇愁造物靳清閒。"]},{"t":"和远老四首 其一","f":"七言绝句","c":["事好休时便好休，不应人尽觅封侯。","归来已快平生志，况有高人来聚头。"]},{"t":"和远老韵二首 其二","f":"七言绝句","c":["欲访天台帛道猷，梦魂先到石桥头。","个中直待桃花放，始得从师烂漫游。"]},{"t":"和远老韵二首 其一","f":"七言绝句","c":["平生痼疾在烟霞，到处林泉是我家。","若也远公容入社，直须酤酒不须茶。"]},{"t":"和陈子良海棠四首 其四","f":"七言绝句","c":["十年栽种满园花，无似兹花艳丽多。","已是谱中推第一，不须还更问如何。"]},{"t":"和陈子良海棠四首 其三","f":"七言绝句","c":["雨后花头顿觉肥，细看还是旧风姿。","坐馀自有香芬馥，不许凡人取次知。"]},{"t":"和陈子良海棠四首 其二","f":"七言绝句","c":["花间春色丽晴空，恼我狂来只绕丛。","试问妖娆谁与比，一株胜却万株红。"]},{"t":"和陈子良海棠四首 其一","f":"七言绝句","c":["春来人物尽熙熙，红紫无情亦满枝。","正引衰翁诗思动，举头那更得君诗。"]},{"t":"和周明瞻秋香五首 其五","f":"七言绝句","c":["已爱清秋霁景鲜，山明水秀竹娟娟。","更来花下成真赏，顿觉飘飘意欲仙。"]},{"t":"和周明瞻秋香五首 其四","f":"七言绝句","c":["山腰水际有馀青，造物多应特禀灵。","桃李无言甘避舍，可怜黄菊强仪刑。"]},{"t":"和周明瞻秋香五首 其三","f":"七言绝句","c":["恼人风味冠江南，浪蕊浮花总觉凡。","对此自宜文字饮，不须更倩玉纤掺。"]},{"t":"和周明瞻秋香五首 其二","f":"七言绝句","c":["月窟仙人冷淡妆，鹅黄衫子翠罗裳。","虽无妖艳誇尘俗，别是人家一种香。"]},{"t":"和周明瞻秋香五首 其一","f":"七言绝句","c":["落叶初辞万木林，谁将翡翠屑寒金。","朝来散入亭前树，着处幽香欲满襟。"]},{"t":"和林大任三首 其三","f":"七言绝句","c":["花绕禅房水更深，静中啼鸟有嘉音。","我来已觉心如水，不用临流更洗心。"]},{"t":"和林大任三首 其二","f":"七言绝句","c":["兰舟泛泛漾轻风，十里桃花一望中。","疑是馀霞天外落，不应花解满山红。"]},{"t":"和林大任三首 其一","f":"七言绝句","c":["融融春色满花源，杨柳阴中系画船。","笑逐鳌头花下去，旌旗夹道鼓渊渊。"]},{"t":"和金功叟二首 其二","f":"七言绝句","c":["君家今岁受恩封，共庆夫夫妇妇同。","况遇诞弥尤可乐，愿拚沉醉似仙翁。"]},{"t":"和金功叟二首 其一","f":"七言绝句","c":["两家诞日俱延客，长恨无缘笑语同。","辄奉朋尊聊介寿，愿言百岁亦如翁。"]},{"t":"和康伯可重阳","f":"七言绝句","c":["过了重阳又一阳，梅开亦拟共壶觞。","病中无复成狂饮，且作前贤醒里狂。"]},{"t":"和梁次张谢得酒见寄四首 其四","f":"七言绝句","c":["平生性僻有诗耽，每恨才悭不得兼。","独嗜君诗无厌斁，从教人笑我多馋。"]},{"t":"和梁次张谢得酒见寄四首 其三","f":"七言绝句","c":["妙龄才气压同升，谈笑端能却五兵。","况复锦囊新且丽，粲如春树万枝荣。"]},{"t":"和梁次张谢得酒见寄四首 其二","f":"七言绝句","c":["春入横塘绿胜醅，更将清浅照寒梅。","试吟秀句临流坐，引得疏枝一晌开。"]},{"t":"和梁次张谢得酒见寄四首 其一","f":"七言绝句","c":["传得仙家不老方，酿成春色瓮头香。","一樽聊尔资杯酌，争似相携入醉乡。"]},{"t":"和梅花前见鹤","f":"七言绝句","c":["双鹤翩翩到我前，与花斗白更争妍。","低头自觉形仪秽，安得飘然跨上天。"]},{"t":"和隐老见怀二首 其二","f":"七言绝句","c":["咫尺经时阻笑言，春归空想给孤园。","一声啼鸟山深处，宴坐蒲团未觉喧。"]},{"t":"和隐老见怀二首 其一","f":"七言绝句","c":["独立溪头怅望时，高人遗我送春诗。","不知春色归何处，月落空庭费梦思。"]},{"t":"和龚漕二首 其二","f":"七言绝句","c":["人生笑口苦难开，故事当修戏马台。","已许为君拚一醉，何妨今日且衔杯。"]},{"t":"和龚漕二首 其一","f":"七言绝句","c":["我老强来分外阃，君才端合在中台。","语离正欲连宵醉，应笑清斋不举杯。"]},{"t":"和潘大卿芍药二首 其二","f":"七言绝句","c":["拂拂轻黄染御衣，出群标韵异繁枝。","此身已分京华隔，不谓天香尚许披。"]},{"t":"和潘大卿芍药二首 其一","f":"七言绝句","c":["落尽群花春已残，忽惊庭下锦新翻。","夜深领客穷清赏，一笑开怀倒数尊。"]},{"t":"和戴解元雄飞瑞香二首 其二","f":"七言绝句","c":["碧玉扶疏自可观，花头缠锦更团圞。","坐来已觉明人眼，况有幽香馥鼻端。"]},{"t":"和戴解元雄飞瑞香二首 其一","f":"七言绝句","c":["芳心似与春风约，绝艳还宜晓日笼。","虽谢幽人持赠我，对花无奈忆山中。"]},{"t":"咏松 其一","f":"七言绝句","c":["古人长抱济人心，道上栽松直到今。","今日若能增种植，会看百世长青阴。"]},{"t":"咏松 其二","f":"七言绝句","c":["古邑荒凉但有松，浓阴夹道势腾空。","行人破暑忙归去，未必茅檐有此风。"]},{"t":"咏松","f":"五言绝句","c":["幸不生涧底，杰出苍苍崖。","岁寒只孤秀，万木非吾侪。"]},{"t":"咏海棠呈子肃","f":"七言绝句","c":["海棠元自有天香，底事时人故谤伤。","不信请来花下坐，恼人鼻观不寻常。"]},{"t":"垂虹闻笛","f":"七言绝句","c":["三十年前此凭栏，醉听渔笛暮江寒。","重来虽复闻三弄，老去终无旧日欢。"]},{"t":"夜与作霖避暑南园登江月台二首 其二","f":"七言绝句","c":["俯瞰江流万尺台，暑天长引好风来。","若为今夕如相避，怀抱何由一快哉。"]},{"t":"夜与作霖避暑南园登江月台二首 其一","f":"七言绝句","c":["坐遍遐观渌照亭，凉飙了不到檐楹。","更登江月还蒸郁，谁道人间夜气清。"]},{"t":"夜饮观风堂龚漕折芙蓉侑酒","f":"七言绝句","c":["灯下看花已可人，此花那更有精神。","不辞今日樽前醉，只恐红妆不是真。"]},{"t":"昔杯渡禅师自西域开山隐静止携五叶松来岁月既远余求此山中之松已化为乌有矣护国远老知余此意遍搜之天台山中得于玉霄峰下移以见饷遂为林下之光因诗以谢之","f":"七言绝句","c":["杯渡移从西域来，一枝五叶翠成堆。","谢师致此为吾寿，使向湖山深处栽。"]},{"t":"松岭","f":"七言绝句","c":["君爱山间十八公，俨然风操出樊笼。","四时已占青青色，更有松黄胜万红。"]},{"t":"败屋有感","f":"七言绝句","c":["甲第巍然数百间，一朝人去顿摧残。","寄言行客休兴叹，但积阴功后代看。"]},{"t":"雨后","f":"七言绝句","c":["破雨冲风万骑趋，人人轻捷过飞凫。","要须直捣天山去，趁取河冰塞槁枯。"]},{"t":"前太守仲求石问留题因和三首 其三","f":"五言绝句","c":["此日老法从，当年穷秀才。","从今归去好，非不遇时来。"]},{"t":"前太守仲求石问留题因和三首 其二","f":"五言绝句","c":["度力难堪事，甘心作弃才。","欲归归未得，却悔出山来。"]},{"t":"前太守仲求石问留题因和三首 其一","f":"五言绝句","c":["不解追时好，尤非治郡才。","故山猿鹤怨，应怪未归来。"]},{"t":"客有善画者取予所和归去来辞图之成轴仍为老者写照于其间感而有作","f":"七言绝句","c":["劳苦形骸不自知，朝来始向画图披。","可怜憔悴今如许，更不归休待几时。"]},{"t":"待雪呈子仪二首 其二","f":"七言绝句","c":["不须坐客苦言归，看取天花满院飞。","已是雪床先到了，夜深应与月交辉。"]},{"t":"待雪呈子仪二首 其一","f":"七言绝句","c":["晓见纷纷满四山，胡为未肯到人间。","化工若解呈新巧，速剪冰花破我颜。"]},{"t":"括苍陈与叟携所撰春秋义例见过书于卷后","f":"七言绝句","c":["独抱麟经三十年，发挥褒贬勒成编。","休嗟当世知音少，自有遗书后代传。"]},{"t":"括苍胡经仲以经术授吾乡子弟仆顷过钱塘得吾兄永言多益及友人孟世功书未尝不以得交经仲为言且以其往还诗什相示已决知经仲非尘埃中人矣春初归自钱塘遂获识经仲于斋馆信数公之知人交道之不朽一年之间凡三相会从容谈笑者盖十许日而诗筒之循环来往曾未尝辍而仆之心犹以不得朝夕见经仲为恨也一日经仲来访席未定乃谓仆曰吾将归乡明年不复来此矣仆念经仲之贤交游中所未有顾世方扰攘会合无期临风语离殆不胜依黯因诵老杜人生足别离之句作五绝","f":"七言绝句","c":["明日离樽难重倾，且停征驭话交情。","知心自古不易得，况是途穷赖友生。"]},{"t":"括苍胡经仲以经术授吾乡子弟仆顷过钱塘得吾兄永言多益及友人孟世功书未尝不以得交经仲为言且以其往还诗什相示已决知经仲非尘埃中人矣春初归自钱塘遂获识经仲于斋馆信数公之知人交道之不朽一年之间凡三相会从容谈笑者盖十许日而诗筒之循环来往曾未尝辍而仆之心犹以不得朝夕见经仲为恨也一日经仲来访席未定乃谓仆曰吾将归乡明年不复来此矣仆念经仲之贤交游中所未有顾世方扰攘会合无期临风语离殆不胜依黯因诵老杜人生足别离之句作五绝","f":"七言绝句","c":["风期久已暗相亲，樽酒论文未厌频。","底事天公苦乖隔，动将离索付骚人。"]},{"t":"括苍胡经仲以经术授吾乡子弟仆顷过钱塘得吾兄永言多益及友人孟世功书未尝不以得交经仲为言且以其往还诗什相示已决知经仲非尘埃中人矣春初归自钱塘遂获识经仲于斋馆信数公之知人交道之不朽一年之间凡三相会从容谈笑者盖十许日而诗筒之循环来往曾未尝辍而仆之心犹以不得朝夕见经仲为恨也一日经仲来访席未定乃谓仆曰吾将归乡明年不复来此矣仆念经仲之贤交游中所未有顾世方扰攘会合无期临风语离殆不胜依黯因诵老杜人生足别离之句作五绝","f":"七言绝句","c":["吾侪生长太平时，不谓年来逢乱离。","此别要烦君自重，相期重筑太平基。"]},{"t":"洪崖","f":"七言绝句","c":["张老升仙不记年，石崖遗迹尚流传。","心期默契真如见，何必追随与拍肩。"]},{"t":"种德堂","f":"七言绝句","c":["我本农家世贱贫，一门相继亦簪绅。","当知来处非今日，莫学诗人只为身。"]},{"t":"览洛中名园记有感","f":"七言绝句","c":["历官冉冉踰三纪，阅世看看近七旬。","更览名园兴废记，愈令人忆故园春。"]},{"t":"贺董伯玉探梅","f":"七言绝句","c":["寄语南枝及早开，莫迟春信待人催。","我今已办千钟酒，准拟花前醉百回。"]},{"t":"送白酒白莲与钟统制钱广文因成二绝 其一","f":"五言绝句","c":["瓮头白酒熟，池上白莲开。","我爱君纯白，聊持荐一杯。"]},{"t":"送白酒白莲与钟统制钱广文因成二绝 其二","f":"五言绝句","c":["白酒方浮玉，白莲仍可人。","赠君飞大白，聊作冷官春。"]},{"t":"送安老","f":"七言绝句","c":["师走丛林不计年，若为犹未了因缘。","万年有路何妨去，透取无生不二禅。"]},{"t":"送朱彦先归乡","f":"七言绝句","c":["西风一夜扫残枝，处处寒砧捣客衣。","我正思归归未得，却于江上送君归。"]},{"t":"送侄赴廷试 其二","f":"七言绝句","c":["一第男儿未足誇，喜传衣钵振吾家。","大廷好上千言对，要使声名播迩遐。"]},{"t":"送侄赴廷试 其一","f":"七言绝句","c":["我是田家本业农，偶然两世到蟾宫。","书生天幸有如此，岂复更忧吾道穷。"]},{"t":"送侄赴廷试 其三","f":"七言绝句","c":["上林跃马看腾骧，父老犹言昔日张。","顾我儿曹殊未学，敢将踪迹继前芳。"]},{"t":"送明老游雁荡五首 其五","f":"七言绝句","c":["遍参尊宿走诸方，老去才能返故乡。","涨水飞云前辈语，他乡莫更久徜徉。"]},{"t":"送明老游雁荡五首 其四","f":"七言绝句","c":["方欣林下共谈禅，底事深公挽出山。","千里同风无道俗，何妨一笑便言还。"]},{"t":"送明老游雁荡五首 其三","f":"七言绝句","c":["吾儿此地偶钟英，绍我家风尚典刑。","所幸吾师知此意，殷勤为我谢山灵。"]},{"t":"送明老游雁荡五首 其二","f":"七言绝句","c":["师到龙湫谒矩罗，为言别久渴心多。","当年见处祥光满，试问今还记得么。"]},{"t":"送明老游雁荡五首 其一","f":"七言绝句","c":["昔年曾作雁山游，倒指今踰四十秋。","叹我岂劳蝴蝶梦，羡师重到大龙湫。"]},{"t":"送津还任","f":"七言绝句","c":["汝到庭闱话未终，若为行色又匆匆。","要知只有归来好，便做三公亦是空。"]},{"t":"送津赴绍兴倅八首 其八","f":"七言绝句","c":["人生万事不如归，只恐归来不及时。","汝若能为陶靖节，我身胜到凤凰池。"]},{"t":"送津赴绍兴倅八首 其七","f":"七言绝句","c":["我辞官路已多时，魂梦今犹畏险巇。","汝既饱谙游宦味，会须早作个归期。"]},{"t":"送津赴绍兴倅八首 其六","f":"七言绝句","c":["出仕曾尘侍从班，退休还得老湖山。","已惭过分无他望，只愿吾儿相对閒。"]},{"t":"送津赴绍兴倅八首 其五","f":"七言绝句","c":["我曾开凿鉴湖田，功竟难成愧昔贤。","汝谒马祠须问讯，此湖兴复是何年。"]},{"t":"送津赴绍兴倅八首 其四","f":"七言绝句","c":["当年我镇卧龙山，曾种千花与万竿。","岁久不知无恙否，因来且为报平安。"]},{"t":"送津赴绍兴倅八首 其三","f":"七言绝句","c":["汝辞秦邸佐名藩，端为亲庭数舍间。","数舍相望虽不远，争如在侧日承颜。"]},{"t":"送津赴绍兴倅八首 其二","f":"七言绝句","c":["山色湖光足自怡，幽栖无一不相宜。","只嫌野外游从少，汝早归来共乐之。"]},{"t":"送津赴绍兴倅八首 其一","f":"七言绝句","c":["读书已负少年时，老大空疏愧我知。","汝肯为余偿此志，虽穷亦是起家儿。"]},{"t":"送朝宗兼简闽帅","f":"七言绝句","c":["年来知我不如公，日日相思恨不逢。","君若见时须问我，为言老子已龙钟。"]},{"t":"香丛","f":"五言绝句","c":["缓步绕芳丛，时时鼻观通。","不须薰百和，满院是香风。"]},{"t":"倚楼","f":"七言绝句","c":["独倚危楼一望长，恼人情处是斜阳。","神州更在斜阳外，纵使无情也断肠。"]},{"t":"夏日游灵隐东园赠东方道人","f":"七言绝句","c":["松竹回环十里阴，一声啼鸟觉山深。","道人睡足北窗下，一榻清风直万金。"]},{"t":"捉月台","f":"七言绝句","c":["谪仙捉月古今传，我访遗踪似未然。","山下浊流长混混，夜深安得水中天。"]},{"t":"桂堂","f":"七言绝句","c":["长恨年年月窟秋，无人共拍酒船浮。","君家双桂开时节，我欲从君载酒游。"]},{"t":"桃花菊 其二","f":"七言绝句","c":["名园看尽好花枝，黄菊施朱独未窥。","应是天怜秋寂寞，故分春色到东篱。"]},{"t":"桃花菊 其一","f":"七言绝句","c":["秋来不谓见春华，疑与春风是一家。","已向枝头开菊蕊，更来菊上作桃花。"]},{"t":"留长河堰","f":"七言绝句","c":["湖山堂下水声寒，夜半琮琤响佩环。","梦寐欲归归未得，却来此处听潺潺。"]},{"t":"真止堂","f":"七言绝句","c":["我有虚堂号真止，坐来万虑清如水。","君今更以止名堂，想见了无尘念起。"]},{"t":"读刘与权壮士歌","f":"七言绝句","c":["满眼烟尘未息戈，禦戎无策奈愁何。","一尊浊酒空庭晚，独自歌君壮士歌。"]},{"t":"酒酣再赋一绝","f":"七言绝句","c":["二年两度到蛾眉，今日还来话别离。","所恨行人难久住，酒阑不见月明时。"]},{"t":"钱丈处和和所寄韩子云约赏梅绝句复用前韵谢之三首 其三","f":"七言绝句","c":["竹符驱我出山来，万事无心付酒杯。","又见江城春到也，伤情却忆故园梅。"]},{"t":"钱丈处和和所寄韩子云约赏梅绝句复用前韵谢之三首 其二","f":"七言绝句","c":["曲生为我惠然来，陡觉春浮潋滟杯。","饮罢冥搜无好语，但将风味属江梅。"]},{"t":"钱丈处和和所寄韩子云约赏梅绝句复用前韵谢之三首 其一","f":"七言绝句","c":["锦囊新句忽传来，字字清如竹叶杯。","要须莫放传杯手，看即归调傅说梅。"]},{"t":"钱广文采芹亭","f":"七言绝句","c":["开明后学日升车，千里文风一旦雄。","池上采芹摇水碧，帐中摛藻映纱红。"]},{"t":"陪梁大谏陈察院同登蒋山","f":"七言绝句","c":["尽室斋心谒梵宫，愿求一语卜穷通。","老夫祇欲归田去，懒把前程问志公。"]},{"t":"寄龚帅 其二","f":"七言绝句","c":["虽喜英贤帅十连，却惭糠秕滥居前。","自知未免人扬簸，愿使衰翁晚节全。"]},{"t":"寄龚帅 其三","f":"七言绝句","c":["行李看看近故庐，梦魂犹自绕洪都。","帅垣暇日登临处，把酒还能话我无。"]},{"t":"寄龚帅 其一","f":"七言绝句","c":["今朝駃步忽来前，报道除书下日边。","阃寄复归贤使者，百城闻命想欣然。"]},{"t":"寄龚漕六首 其六","f":"七言绝句","c":["闻公新有帅垣除，一路逢人尽贺予。","瓜代得贤人尚喜，予心欢喜更何如。"]},{"t":"寄龚漕六首 其五","f":"七言绝句","c":["天朝未许投簪去，我幸已成全璧归。","全璧归来何所憾，暮年只是惜分违。"]},{"t":"寄龚漕六首 其四","f":"七言绝句","c":["葺得南园过一春，无从再见物华新。","匆匆相别休相忆，已有风流贤主人。"]},{"t":"寄龚漕六首 其三","f":"七言绝句","c":["贡院门前并北湖，有田百亩却荒芜。","愿君种取花千树，付与邦人作画图。"]},{"t":"寄龚漕六首 其二","f":"七言绝句","c":["几年湮塞豫章沟，岁岁民间有水忧。","我意若非公善后，不应城里解通舟。"]},{"t":"寄龚漕六首 其一","f":"七言绝句","c":["自古知心不易逢，君心还与我心同。","纵令自择交成契，更有何人得似公。"]},{"t":"寄朝宗二首 其一","f":"七言绝句","c":["湖水春来拍岸平，山光幻出小蓬瀛。","幽深未许凡人到，只待君来共落成。"]},{"t":"寄韩子云二首 其二","f":"七言绝句","c":["点检枝头春已来，不应辜负掌中杯。","与君索笑须宜早，莫待城头吹落梅。"]},{"t":"寄韩子云二首 其一","f":"七言绝句","c":["去岁花时许我来，花前竟阻共衔杯。","如今又是花开也，忍使衰翁独看梅。"]},{"t":"寄韩子云总领","f":"七言绝句","c":["与君有约看梅花，准拟尊前共笑歌。","花已飘零君不至，夕阳芳草奈愁何。"]},{"t":"寄题隐静三首 其三","f":"七言绝句","c":["我师一出几何年，闻欲东归未有缘。","何日扶藜能过我，湖山深处共谈禅。"]},{"t":"寄题隐静三首 其二","f":"七言绝句","c":["向来连岁守江城，到处题诗满户庭。","独欠兹山一转语，倩师与我谢山灵。"]},{"t":"寄题隐静三首 其一","f":"七言绝句","c":["五峰双涧旧标名，我恨当年去不成。","却羡个中人自在，饱看山色听泉声。"]},{"t":"得乡书","f":"七言绝句","c":["闻道交亲知我还，欢迎竞欲越乡关。","我于乡里初无补，又复劳人祇汗颜。"]},{"t":"得子云和篇约元宵见访再用前韵以速之二首 其二","f":"七言绝句","c":["花开本是待春来，天遣春先荐我杯。","君莫疑花开太早，相思一夜发寒梅。"]},{"t":"得子云和篇约元宵见访再用前韵以速之二首 其一","f":"七言绝句","c":["闻道元宵始肯来，见梅说与且停杯。","行将有客同清赏，雅致高标一似梅。"]},{"t":"得家书喜津病愈","f":"七言绝句","c":["老怀郁郁苦难舒，忽报吾儿病已除。","便觉身心无个事，万钱不抵一封书。"]},{"t":"悼王习之","f":"七言绝句","c":["两州佳政万人传，一旦那知遂溘然。","到底久生从古少，要须乘健早归田。"]},{"t":"晚晴三首 其三","f":"七言绝句","c":["三分春色二分过，那更连宵风雨多。","试向园中问消息，不知还尚有花么。"]},{"t":"晚晴三首 其二","f":"七言绝句","c":["时巡中外已欢呼，那值天晴喜浴凫。","路上捷音良可庆，王师所至若摧枯。"]},{"t":"晚晴三首 其一","f":"七言绝句","c":["洗尽妖氛喜乍晴，风生万马四蹄轻。","天时人事俱相契，敢有纤儿更弄兵。"]},{"t":"梅庄主人袖诗见过累日欲得次韵以汩汩无暇且和一绝","f":"七言绝句","c":["偶驱小队踏苍苔，无数梅花照眼开。","更有高人同胜赏，此行端是不虚来。"]},{"t":"梅花下饮茶又成二绝 其二","f":"七言绝句","c":["强拈茶碗对梅花，应是花神笑我多。","更取香醪拚一醉，不禁风味恼人何。"]},{"t":"梅花下饮茶又成二绝 其一","f":"七言绝句","c":["昨日花前酒太过，今朝怕见近流霞。","不应辜负花枝去，且嗅清香倍饮茶。"]},{"t":"梅花下闻角声","f":"七言绝句","c":["兀坐江城厌寂寥，喜逢春色上梅梢。","寄言画角休吹遍，留与铃斋作淡交。"]},{"t":"梅亭盖旧太守徐公禋所作传者谓公得庾岭梅移种于此故创斯亭余来相距未六十年曩日之梅已无复有感时追往因取野梅环植之仍赋二绝 其二","f":"七言绝句","c":["种梅我始效徐公，已觉幽香鼻观通。","寄语后人无剪伐，要令凋郡识春风。"]},{"t":"梅亭盖旧太守徐公禋所作传者谓公得庾岭梅移种于此故创斯亭余来相距未六十年曩日之梅已无复有感时追往因取野梅环植之仍赋二绝 其一","f":"七言绝句","c":["已无庾岭旧时梅，但见梅亭向水开。","遐想风流犹彷佛，更将梅绕四檐栽。"]},{"t":"梅怨 其二","f":"七言绝句","c":["我与梅花素有期，故应花怨我轻离。","巡檐索笑宁无日，少待归来酒作池。"]},{"t":"梅怨 其一","f":"七言绝句","c":["几年不见主人归，及见开时又别离。","若也有花无分赏，何如休种满园池。"]},{"t":"移梅北隩和黄清表韵","f":"七言绝句","c":["自惭面目久尘埃，拟对冰姿一笑开。","闻道前村连夜发，岂辞健步远移来。"]},{"t":"雪后观梅 其二","f":"七言绝句","c":["春色三分已一分，江梅犹自占青春。","有花堪折须拚醉，莫待东风吹作尘。"]},{"t":"雪后观梅 其一","f":"七言绝句","c":["雨声才歇雪漫漫，深恐梅花不耐寒。","破晓踏泥来问讯，细看枝上喜平安。"]},{"t":"领客赏海棠雪作 其一","f":"七言绝句","c":["绝艳妖娆压众芳，况来烛下逞新妆。","引将姑射神人到，亦逐春风上下狂。"]},{"t":"领客赏海棠雪作 其二","f":"七言绝句","c":["撩拨游人思不禁，也缘尤物荡人心。","今宵雪向花间作，应妒此花红太深。"]},{"t":"领客赏梅 其二","f":"七言绝句","c":["只拟花开把酒杯，南枝忽递暗香来。","径须领客同清赏，莫待城头吹落梅。"]},{"t":"领客赏梅 其一","f":"七言绝句","c":["经年相别阻传杯，忽见梅枝入眼来。","今日劝君休惜醉，不应辜负腊前梅。"]},{"t":"喜雨","f":"七言绝句","c":["正忧麦槁井泉乾，一雨中宵忽沛然。","莫恨梅花憔悴去，且欣新绿尽归田。"]},{"t":"喜雨三首 其三","f":"七言绝句","c":["畏暑停骖憩驿亭，不知郭外雨如倾。","晚行但觉通衢湿，凉入郊墟分外清。"]},{"t":"喜雨三首 其二","f":"七言绝句","c":["昨朝偶得碧琳腴，不敢濡唇畏暑涂。","雨过凉生襟袂爽，不妨倾倒且踟蹰。"]},{"t":"喜雨三首 其一","f":"七言绝句","c":["铄石流金苦异常，行人谁不困秋阳。","狂风忽送排檐雨，涤尽炎威作晚凉。"]},{"t":"喜晴","f":"七言绝句","c":["始喜晴天照眼明，忽惊风雨报秋声。","天公也念悲秋客，还扫群阴作晚晴。"]},{"t":"寒梅","f":"七言绝句","c":["冰玉精神绝点埃，人间无物似寒梅。","凌霜傲雪浑閒事，最是欺春不逐来。"]},{"t":"渡钱塘江","f":"七言绝句","c":["万顷烟波一叶轻，风来枕上觉凉生。","我行触热浑无奈，却喜身心得顿清。"]},{"t":"游月岩 其二","f":"七言绝句","c":["平生性僻喜岩居，事不如人只守株。","拟欲结茅依石罅，仙人还许我来无。"]},{"t":"游月岩 其一","f":"七言绝句","c":["仙人蜕骨几何年，姓氏于今秘不传。","石壁苍崖无处问，空馀洞府尚依然。"]},{"t":"游仙都观五首 其五","f":"七言绝句","c":["登览兹山古到今，流传今有几何人。","如今胜践悬知少，况有新诗为写真。"]},{"t":"游仙都观五首 其四","f":"七言绝句","c":["人已乘龙去不还，尚馀双鹤不知年。","坐来顿觉尘寰隔，始信壶中别有天。"]},{"t":"游仙都观五首 其三","f":"七言绝句","c":["闻道山颠有鼎湖，莲花还似旧时无。","轩辕去后空车辙，疑此山川即旧都。"]},{"t":"游仙都观五首 其二","f":"七言绝句","c":["策杖行行入翠微，步虚山下久忘归。","幽栖宜有中林士，何事斯人近世稀。"]},{"t":"游仙都观五首 其一","f":"七言绝句","c":["来访仙人古玉虚，山前有客指迷涂。","烟云渺渺孤峰绝，松竹森森一径迂。"]},{"t":"登舟","f":"七言绝句","c":["天怜行客困阳秋，许舍车徒上小舟。","十里好风袪滞思，一溪寒水助清游。"]},{"t":"登进贤县治后山望云亭","f":"七言绝句","c":["古木千章翠欲交，白云疑只在松梢。","公馀莫惜频登眺，无限风烟满四郊。"]},{"t":"登望云亭","f":"楚辞体","c":["记得来时上此亭，亭荒有景亦徒清。","如今亭与景俱胜，水倍秀兮山倍明。"]},{"t":"谢陈詹山惠蜡梅","f":"七言绝句","c":["岁晚相逢眼已明，一枝还复见高情。","幽香不与江梅共，要与夫君斗独清。"]},{"t":"赏山茶","f":"七言绝句","c":["向晚佳人逞艳妆，偶随月姊到山房。","自怜老去无佳句，亦复冥搜为发扬。"]},{"t":"鲁漕惠鹿鹤花果","f":"七言绝句","c":["镂果团缯宛似真，尊前一见喜生春。","感公持此为余寿，益悟浮生是幻身。"]},{"t":"感花 其三","f":"七言绝句","c":["雨脚才收拟杖藜，檐前依旧又垂垂。","倘余有分花间醉，会有风和日暖时。"]},{"t":"感花 其四","f":"七言绝句","c":["纵令日日醉春风，已恨花无十日红。","何事东君长作恶，不容春色丽晴空。"]},{"t":"感花 其五","f":"七言绝句","c":["千花到底不如梅，胜赏犹宜踏雪来。","今日满天长是雨，如何花下得徘徊。"]},{"t":"感花 其一","f":"七言绝句","c":["正欲持杯赏万红，却遭连日雨兼风。","种花欲看难如此，可是衰翁赋分穷。"]},{"t":"感花 其六","f":"七言绝句","c":["春来日日欲寻春，乐此疏慵老大身。","岂料青春今过半，萧萧风雨却愁人。"]},{"t":"感花 其八","f":"七言绝句","c":["一雨绵绵不暂停，天公于此底无情。","不应直待花飘尽，始放阳和作好晴。"]},{"t":"感花 其二","f":"七言绝句","c":["年来老病苦相侵，已是伤春不自禁。","那更雨声长在耳，连朝滴碎惜花心。"]},{"t":"感花 其七","f":"七言绝句","c":["嗟我明年是七旬，此生能见几番春。","凭谁为补青天漏，放出春光处处新。"]},{"t":"新创太平楼未及落成而去漫留一绝","f":"七言绝句","c":["登临祇待此楼成，要与邦人乐太平。","甫及楼成余已去，匆匆一眺但凝情。"]},{"t":"睡中闻莺","f":"七言绝句","c":["解鞍萧寺憩清幽，睡里忽闻黄栗留。","惊破梦魂何可恨，得知身在浙江头。"]},{"t":"睡仙楼","f":"七言绝句","c":["此垆当日饮神仙，醉倒和衣壁上眠。","酒醒兴阑人不见，但留佳话古今传。"]},{"t":"置酒与五客饯行因成一绝","f":"七言绝句","c":["送尽行人我独留，老夫无计解离忧。","劝君今夜休辞醉，明日江山总是愁。"]},{"t":"蒙恩易镇豫章丐假还乡途中偶成十七首 其十七","f":"五言绝句","c":["千尺石屏雄，屏边列数峰。","巍然不可犯，真是镇疆封。"]},{"t":"蒙恩易镇豫章丐假还乡途中偶成十七首 其十六","f":"五言绝句","c":["两山夹苍烟，双瀑挂峭壁。","汹涌非一朝，倾泻几千尺。"]},{"t":"蒙恩易镇豫章丐假还乡途中偶成十七首 其十五","f":"五言绝句","c":["兹岭别二年，今朝又重过。","过了还复来，哀哉蚁旋磨。"]},{"t":"蒙恩易镇豫章丐假还乡途中偶成十七首 其十四","f":"五言绝句","c":["苍崖崛地耸，飞瀑从天下。","一岭跨两州，千年无九夏。"]},{"t":"蒙恩易镇豫章丐假还乡途中偶成十七首 其十三","f":"五言绝句","c":["睡里闻风雨，吾行拟暂停。","起来搔首坐，喜见一天星。"]},{"t":"蒙恩易镇豫章丐假还乡途中偶成十七首 其十二","f":"五言绝句","c":["游鱼跳水面，幽鸟啭山腰。","各随飞潜性，人犹恋市朝。"]},{"t":"蒙恩易镇豫章丐假还乡途中偶成十七首 其十一","f":"五言绝句","c":["雨馀江色净，风过稻花香。","客里逢清旷，何妨且纳凉。"]},{"t":"蒙恩易镇豫章丐假还乡途中偶成十七首 其十","f":"五言绝句","c":["崇阁瞰方池，池边绿树围。","披襟临水坐，宁复畏炎威。"]},{"t":"蒙恩易镇豫章丐假还乡途中偶成十七首 其九","f":"五言绝句","c":["村径迷南北，晨兴乃错行。","悟来还已远，却悔早贪程。"]},{"t":"蒙恩易镇豫章丐假还乡途中偶成十七首 其八","f":"五言绝句","c":["自江至吾庐，七日喜及半。","却恐席未温，又过江南岸。"]},{"t":"蒙恩易镇豫章丐假还乡途中偶成十七首 其七","f":"五言绝句","c":["中夜不能眠，颇疑天有雨。","寒燠自古然，不应冷如许。"]},{"t":"蒙恩易镇豫章丐假还乡途中偶成十七首 其六","f":"五言绝句","c":["剧暑当三伏，新凉似九秋。","日光还欲吐，云影未全收。"]},{"t":"蒙恩易镇豫章丐假还乡途中偶成十七首 其五","f":"五言绝句","c":["沙虚防败岸，舟小怯惊湍。","行路难如此，争如野处安。"]},{"t":"蒙恩易镇豫章丐假还乡途中偶成十七首 其四","f":"五言绝句","c":["方困长涂滑，俄逢赫日明。","只忧开太早，却恐雨还生。"]},{"t":"蒙恩易镇豫章丐假还乡途中偶成十七首 其三","f":"五言绝句","c":["触目尽陂塘，山光接水光。","近来仍雨足，莫道是山乡。"]},{"t":"蒙恩易镇豫章丐假还乡途中偶成十七首 其二","f":"五言绝句","c":["官舍似邮传，宦游如路岐。","吾年行七十，安用苦奔驰。"]},{"t":"蒙恩易镇豫章丐假还乡途中偶成十七首 其一","f":"五言绝句","c":["处处是红蕖，分明似画图。","匆匆看不尽，归对小西湖。"]},{"t":"蜡梅二首 其二","f":"七言绝句","c":["园林摇落独芬芳，未让江梅雪里香。","还恐人嫌梅太白，故来枝上尽涂黄。"]},{"t":"蜡梅二首 其一","f":"七言绝句","c":["谁将栗玉刻蜂房，巧向梢头取次妆。","羞得江梅都避舍，满园不见一枝芳。"]},{"t":"嘲钦师","f":"七言绝句","c":["师与予心总爱山，从来已许伴予閒。","若为一出俄经月，却恋尘凡未肯还。"]},{"t":"滕王阁","f":"七言绝句","c":["尽道滕王阁太卑，合新旧观复雄规。","我来兴葺非难事，却恐俱为识者嗤。"]},{"t":"题心远轩二首 其二","f":"七言绝句","c":["扁榜当年我命名，喜君心与迹双清。","眼前风物浑如旧，但觉庭前春草生。"]},{"t":"题心远轩二首 其一","f":"七言绝句","c":["山居我欲避嚣尘，尚觉门庭俗客频。","羡尔结茅当道左，一轩风月作閒人。"]},{"t":"题日涉园","f":"五言绝句","c":["幽园足佳趣，散策日经行。","岁久禽鱼熟，人来自不惊。"]},{"t":"题圭师松云庵","f":"七言绝句","c":["一瓶一钵一枝筇，皓首归来万事慵。","应笑白云犹世态，却来庵外媚孤松。"]},{"t":"题许倅浮香亭二绝 其一","f":"七言绝句","c":["一新栏槛水中央，更植疏梅向水傍。","只恐花繁亭太小，黄昏无处著清香。"]},{"t":"题许倅浮香亭二绝 其二","f":"七言绝句","c":["为爱梅花不自禁，拟分风月到花阴。","水深草满都迷路，祇向暗浮香处寻。"]},{"t":"题枕流亭","f":"七言绝句","c":["山涵倒影新晴后，水漾圆花乍雨时。","每到凭栏心似镜，细看无一不相宜。"]},{"t":"题金山四首 其四","f":"七言绝句","c":["人言海上有三山，弱水瀰茫去路难。","若欲目前寻彷佛，只须来此凭栏干。"]},{"t":"题金山四首 其三","f":"七言绝句","c":["北望瓜洲咫尺间，向来白骨积如山。","欲论旧事慵开口，且对高僧共说闲。"]},{"t":"题金山四首 其二","f":"七言绝句","c":["老大疏慵百不堪，倦游犹未脱征衫。","君王若许投簪去，拟与头陀共此岩。"]},{"t":"题金山四首 其一","f":"七言绝句","c":["江上经行四十秋，今朝始得驻扁舟。","老夫宁复重来日，欲去殷勤更少留。"]},{"t":"题总持寺龙井","f":"七言绝句","c":["洞庭归去几何年，旱岁犹来泽我田。","我访遗踪虽已泯，灵泉百尺尚依然。"]},{"t":"题钟路分见一轩二首 其二","f":"七言绝句","c":["懒将功业勒燕然，闭户深居二十年。","嗟尚强颜纡郡绂，老来犹未得归田。"]},{"t":"题钟路分见一轩二首 其一","f":"七言绝句","c":["名利场中车马尘，区区有愧百年身。","如君未老甘闲退，眼底今方见一人。"]},{"t":"题阅岁亭","f":"五言绝句","c":["岁月催人老，少年安在哉。","羡君杯酒里，日日见花开。"]},{"t":"题蛾眉亭用内翰沈公韵","f":"七言绝句","c":["几多去棹与来帆，竞利奔名一水间。","应怪行人浑不悟，临流长是蹙眉山。"]},{"t":"题戴雄飞腴轩诗","f":"七言绝句","c":["四壁萧然万卷书，时人莫认作癯儒。","他年得志英华发，始信胸中道味腴。"]},{"t":"题臞庵","f":"七言绝句","c":["轻视浮名若一毛，名园百亩占江皋。","三贤祠宇谁重葺，何不添公作四高。"]},{"t":"憩慈云寺","f":"七言绝句","c":["幽人不见许玄度，千载徒存旧梵宫。","水竹回环犹可爱，徘徊山下想遗风。"]},{"t":"赠方山人二首 其二","f":"七言绝句","c":["故山久已办菟裘，得去欣闻止在秋。","涉世安能长戚戚，收心只欲罢休休。"]},{"t":"赠方山人二首 其一","f":"七言绝句","c":["日者俱云我未归，独君算我有归期。","仍言不出三秋里，东望家山喜可知。"]},{"t":"赠余居士二首 其二","f":"七言绝句","c":["我老祇思还旧隐，君今更为卜新阡。","馀生得此夫何欠，所欠归来一溘然。"]},{"t":"赠余居士二首 其一","f":"七言绝句","c":["君知我意欲休官，却道如今未得閒。","万事无求惟一退，天公于此不应悭。"]},{"t":"赠张发","f":"七言绝句","c":["日给都来能几何，汝能受少却辞多。","试询世上无厌者，还有何人肯恁么。"]},{"t":"赠远老","f":"七言绝句","c":["一瓶一钵自由身，聊向江南玩水云。","踏遍千山并万壑，却归林下炷炉薰。"]},{"t":"濠水累年不泄鱼既充牣每触热辄死余既浚治市河因开水门导之入江遂作放鱼二绝 其一","f":"七言绝句","c":["局促洿池几岁鱼，想应日日念江湖。","如今放汝非无意，亦欲天公放老夫。"]},{"t":"濠水累年不泄鱼既充牣每触热辄死余既浚治市河因开水门导之入江遂作放鱼二绝 其二","f":"七言绝句","c":["我今纵汝入江中，好趁风雷早化龙。","只恐为龙行雨苦，碧波深处且从容。"]},{"t":"藏云寺有海棠一树在僧舍后竹篱荆棘之间余因劝耕偶见之遣兵移植于堂下仍赋一绝以纪之","f":"七言绝句","c":["海棠一树竹篱根，密掩深藏若避人。","移向亭前端有意，要令山下尽知春。"]},{"t":"九日和向巨源送行韵","f":"七言律诗","c":["世事无穷生有涯，羞将白发对黄花。","一江秋水涵初雁，万里暮天飞落霞。","昔日自怜长作客，今朝方喜得还家。","尊前话别宁辞醉，后夜相思月满沙。"]},{"t":"二儿纳妇有感","f":"七言律诗","c":["老乘一障楚江滨，无奈星星鬓影新。","客里情怀那似旧，忙中日月不知春。","若为经岁抛泉石，犹把非才玷缙绅。","还尽此生儿女债，盍归林下作闲人。"]},{"t":"二十八日出郊劝农陈泽民见示佳作因次来韵","f":"七言律诗","c":["雨多晴少恐妨农，相劝欣逢日出东。","烟蔼已收霄汉外，江山如在画图中。","相看且喜头俱白，一醉休辞颊暂红。","万事要从勤苦得，莫言丰歉在天公。"]},{"t":"二公见和又成一首寄之","f":"七言律诗","c":["忆昔同台接胜游，相期端不愧清流。","一时人物存无几，百岁光阴挽不留。","老去只思陶靖节，向来尤叹薛居州。","亦闻聚首时倾倒，应笑衰翁守故丘。"]},{"t":"二月晦日劝耕石城三首 其三","f":"五言律诗","c":["兀坐无聊赖，所期怀抱开。","偶驱千骑出，还得十朋来。","遣兴非无句，消愁亦有杯。","此心终不乐，祇是忆天台。"]},{"t":"二月晦日劝耕石城三首 其二","f":"五言律诗","c":["经年萦吏役，今日作春游。","梅雪随风去，桃花逐水流。","已惊时节晚，还叹物华休。","扰扰终何补，归与老一丘。"]},{"t":"二月晦日劝耕石城三首 其一","f":"五言律诗","c":["春晓喜新晴，聊为野外行。","残花红雨乱，垂柳绿丝轻。","路入藏云寺，山围走马城。","空馀怀古意，往事与谁评。"]},{"t":"二月望日三七侄移庖于休休堂约四老人为送春之集拙者预一老之数因成八句","f":"七言律诗","c":["光阴过眼似奔轮，谁保生前梦幻身。","四老共成三百岁，一时已胜万千人。","得閒对酒须拚醉，乘健看花莫厌频。","勿谓病多衰已甚，尚堪开口送残春。"]},{"t":"十五夜与朝宗对月把酒朝宗屡怀归因赋二首 其二","f":"七言律诗","c":["雾捲云收月迸光，一时烦浊变清凉。","怪来坐上深无暑，疑是山间已有霜。","老去岂期身尚健，閒中且以酒为忙。","故人若也坚辞醉，忍负良宵月满床。"]},{"t":"十五夜与朝宗对月把酒朝宗屡怀归因赋二首 其一","f":"七言律诗","c":["人间无处避炎光，赖有湖山六月凉。","清夜已欣天似水，长空还爱月如霜。","我将乘兴拚沉醉，君苦怀归有底忙。","试问今宵能饮否，更来月下对胡床。"]},{"t":"十六夜再登月台","f":"七言律诗","c":["虚度中秋颇动怀，今宵却再上高台。","强延风月虽聊尔，一对江山亦快哉。","小子仍携竹叶至，同僚还折桂枝来。","老夫为尔牵诗兴，笑向花前覆一杯。"]},{"t":"又陈伯明知郡远寄诗篇因次韵二首 其二","f":"七言律诗","c":["喜到旧家山水乡，依然山色与湖光。","此身宛在真仙窟，回首空怀太守章。","岂意新诗犹见及，尚言故郡不相忘。","自怜秕政无遗爱，安得人思蔽芾棠。"]},{"t":"又陈伯明知郡远寄诗篇因次韵二首 其一","f":"七言律诗","c":["信笔题诗不记篇，聊凭赋咏写林泉。","閒来倚杖云千嶂，睡起凭栏月一川。","野性已安三径里，吟魂犹绕两湖边。","何时更许陪清话，复把深杯手自传。"]},{"t":"又和陈天予","f":"七言律诗","c":["边敌临江强指麾，狂图欲效白登围。","一朝殄灭妖氛净，万里欢传盛事稀。","故国山河看克复，中原父老徯来归。","六飞便好乘时进，顺取天心莫失机。"]},{"t":"又和金克家送春","f":"七言律诗","c":["春来纵使日衔杯，老去逢春能几回。","幸有良朋同雅集，不妨烂醉罄馀罍。","羞看落絮愁盈抱，强对残花泪满腮。","惆怅又为经岁别，莫辞花下少徘徊。"]},{"t":"三月十一日风雹","f":"七言律诗","c":["向晚欣逢霁色开，方思花下共衔杯。","一时雨雹排檐急，万里风云捲地来。","扫荡千花真可恨，摧残二麦亦堪哀。","赏心乐事俱休矣，惆怅青春去不回。"]},{"t":"与江朝宗丁彦功饮酒梅花下二首 其二","f":"五言律诗","c":["一笑未易得，今朝岂偶然。","故园方自适，我辈更相便。","好月好花夜，不寒不暖天。","莫辞拚一醉，为我棹觥船。"]},{"t":"与江朝宗丁彦功饮酒梅花下二首 其一","f":"五言律诗","c":["挈榼西园去，花光照月华。","共看花上月，肯负月中花。","酒与花俱白，人如月不瑕。","且陪月花醉，何用苦思家。"]},{"t":"与鹿郎中","f":"七言律诗","c":["思到高人见一堂，经年魂梦镇飞扬。","抱疴已恨身无力，拗俗还疑路有妨。","聊寄一樽牵酒兴，更凭五字恼诗肠。","巡檐应索梅花笑，无计从君醉几场。"]},{"t":"乞身不获再和","f":"七言律诗","c":["老合休官况七旬，我非辞富欲居贫。","也知光景无多日，更觉筋骸不逮人。","岂谓九重恩未替，复颁一札意犹亲。","囊封再上终期允，已对苍穹誓此身。"]},{"t":"大阅即事书怀 其二","f":"七言律诗","c":["懒散无堪合杜门，十连帅阃若为分。","仁风尚可扬千里，勇气安能作六军。","戈甲纷纷徒曜日，旌旗猎猎漫连云。","归来夹道人争看，应笑苍颜老使君。"]},{"t":"山居归来恰一年有感","f":"七言律诗","c":["去岁兹辰始息肩，俄然日月已周天。","经营小隐虽云毕，栽种清阴苦未圆。","湖畔百年多古木，山前一望足平川。","从嗟白发催吾老，能享林泉得几年。"]},{"t":"中秋后一夕烟雨楼玩月","f":"七言律诗","c":["危楼百尺俯层城，烟敛云收眼更明。","四面月华千顷白，一天秋气十分清。","昨宵欲见浑无计，今夕相看似有情。","又值病夫慵对酒，赏心乐事信难并。"]},{"t":"五月五日领客泛舟","f":"七言律诗","c":["要同佳客濯清泉，却下危楼上画船。","拭目已看云际月，洗心还爱水中天。","更无暑气侵尊俎，但有薰风入管弦。","我欲就闲行作别，且拚一醉共陶然。"]},{"t":"仆平日闻有此生待足何时足未老得闲方是闲之句每叹服之恨不知作者姓名一日与鲁漕话次方闻此诗乃福唐余倅所作鲁继录全诗及余君所梦始末见示读之使人益起怀归之兴因成小诗以记其事","f":"七言律诗","c":["寒士叨尘分已踰，不为归计待何如。","暮年光景那能久，浮世荣华总是虚。","此去直须甘澹泊，个中元自有乘除。","因公拈起余君话，愈使衰翁忆故庐。"]},{"t":"元夕用胡经仲所寄韵呈辛倅及诸僚友","f":"七言律诗","c":["星斗潜移下九天，满城如昼酒如泉。","当时行乐陪千骑，今日重来恰十年。","灯烛光中春更好，绮罗丛里月争妍。","诸君莫惜长鲸量，要向樽前中圣贤。"]},{"t":"元夕有感","f":"七言律诗","c":["当涂连岁看烧灯，又见洪都烂满城。","紫陌人疑春欲晓，清宵天放月争明。","老逢好景知能几，暗数流年祇自惊。","亦拟樽前成一笑，吾衰无复旧心情。"]},{"t":"元宵雪作因成短句","f":"七言律诗","c":["天公着意做元宵，陡使新春乐事饶。","已放金莲开陆地，更疑银阙下云霄。","坐中星斗浑相照，庭下琼瑰更乱飘。","佳客莫辞通夕醉，要令来岁记今朝。"]},{"t":"六鹤中偶一鹤折翅","f":"五言律诗","c":["皓鹤相从久，衰颜每为开。","忽闻渠翅折，频使我心摧。","本意俱仙去，那知偶祸来。","纵令医得活，无复见毰毸。"]},{"t":"开河毕功喜而有作","f":"七言律诗","c":["污河积水困薰蒸，开凿那知不日成。","野水尽从檐下过，客舟还傍市中行。","江山自昔天然秀，人物从今分外清。","本为此邦开眼目，老夫双目亦增明。"]},{"t":"忆昔","f":"五言律诗","c":["忆昔从吾友，兹焉事笔耕。","萤窗秋夜短，莲社晚风清。","乱后成陈迹，重来怆故情。","惟馀云水客，依旧戏长鲸。"]},{"t":"忆鹿鹤","f":"七言律诗","c":["山中鹿鹤久相疏，恨不归来与汝俱。","飞舞尚如前日否，奔腾还上后山无。","不闻警露来庭下，犹想衔花近座隅。","叹我素钟山野性，从来与汝本无殊。"]},{"t":"月下独酌有怀梁丈因和前韵以寄且约为明夜之集","f":"七言律诗","c":["晚来清跸驻旌麾，月色分明彻四围。","对景已欣群动息，仰天还觉众星稀。","如今路入中原去，看即春从上苑归。","况是升平时节近，一尊相属且忘机。"]},{"t":"王百洪遭旱经火之后赴官荆南作诗勉之","f":"七言律诗","c":["莫将外物挠胸中，旱魃从他更祝融。","道业不应缘火尽，生涯会复值年丰。","事经盘错才方见，诗到羁穷句始工。","休叹徒劳淹幕府，要君努力振家风。"]},{"t":"王瞻叔参政寄惠云笈经因成四韵奉酬","f":"七言律诗","c":["老来犹未返林泉，终日区区亦可怜。","拟扣玄关求至道，喜披云笈探真筌。","他时使我离尘境，今日由君结妙缘。","莫谓骨凡难变化，丹成鸡犬尚升仙。"]},{"t":"见市上有卖海棠者怅然有感","f":"七言律诗","c":["连年踪迹滞江乡，长忆吾庐万海棠。","想得春来增艳丽，无因归去赏芬芳。","偶然担上逢人卖，犹记樽前为尔狂。","何日故园修旧约，剩烧银烛照红妆。"]},{"t":"加恩进秩有作","f":"七言律诗","c":["庆典施恩及万方，老臣遭遇亦非常。","顿加多邑惭非称，倍进崇阶惧莫当。","自念生来无此望，却忧福过有馀殃。","病躯莫效循墙避，且上天庭控免章。"]},{"t":"北山席上见梅偶成","f":"七言律诗","c":["闻道前村梅已开，有心踏月共徘徊。","谁知白日匆匆过，竟阻青鞋得得来。","席上相逢如有旧，尊前伫立恨无媒。","楼头且莫横孤管，我欲今宵醉百杯。"]},{"t":"去郡日寄居诸公作饯即席奉呈","f":"七言律诗","c":["三年江上守孤城，日日思归去未能。","虽愧憩棠无惠政，却欣伐木有良朋。","花开后圃春同醉，月满高楼夜共灯。","别后要须俱自爱，从今拭目看飞腾。"]},{"t":"四月六日同江朝宗花下饮","f":"七言律诗","c":["十分拟共醉花枝，底事君来苦后期。","芍药阶前犹烂熳，酴醾架上已离披。","春归又是辜杯酒，老去还应惜岁时。","今日要须拚酩酊，从教人笑赏花迟。"]},{"t":"归来到红梅下有感","f":"七言律诗","c":["惜花端拟醉花时，不谓花开失素期。","去日横枝才蓓蕾，归来满树已离披。","虽知胜赏输同舍，尚爱馀芳绕曲池。","花亦念予情不浅，更留残萼索题诗。"]},{"t":"未腊已见四白偶得数语呈子寿且述挽留之意","f":"七言律诗","c":["人言三白兆丰年，四白欣逢向腊前。","细糁芦花初着地，乱飘柳絮忽漫天。","雅宜领客登台上，正欲开尊向酒边。","乐岁幸君同赋咏，若为归棹遽翩然。"]},{"t":"生日","f":"七言律诗","c":["藜杖纶巾度几春，紫袍赪带一番新。","恩荣可但将延世，渥泽还欣再及亲。","已见里中誇盛事，何妨林下作闲人。","年踰七十仍希有，寿酒须拚饮百巡。"]},{"t":"生朝有感","f":"五言律诗","c":["姑溪来几日，两度见生朝。","亲旧三年隔，乡关千里遥。","梅还开旧树，柳更长新条。","只有双蓬鬓，天公不见饶。"]},{"t":"生朝有感","f":"七言律诗","c":["每恨生朝天一涯，今年却喜得还家。","渐看寒谷回春律，愈使衰翁感岁华。","客至宁辞倾竹叶，老来能醉几梅花。","馀生祇愿长如此，浮利浮名未足誇。"]},{"t":"用天予贡院韵以饯行色","f":"七言律诗","c":["直气如君世莫双，笑人老死利名场。","一言龃龉身虽去，万口咨嗟道愈光。","舌在何妨居泽国，时来会见佐岩廊。","人间荣辱浑休问，日饮醇醪计亦长。"]},{"t":"用王龟龄韵题五柳堂","f":"五言律诗","c":["久矣斯堂废，重兴赖有公。","双溪修故事，五柳振遗风。","顿觉烟光好，端由气味同。","莫言官独冷，长在绿阴中。"]},{"t":"用金克家韵赋梅花","f":"七言律诗","c":["我赋梅花逼古人，人疑和靖是前身。","祇思长向花前醉，不厌闲来树下频。","俗眼但知誇洁白，老怀端是爱清真。","大家管领须宜早，莫待飘零作地茵。"]},{"t":"用前韵示三七侄","f":"七言律诗","c":["吾家小阮亦贤哉，又得携壶为我来。","应念难逢重九节，要陪痛饮十分杯。","头添白发那能久，眼看黄花有几回。","颇恨病衰鲸量减，只将笑口为君开。"]},{"t":"立春","f":"七言律诗","c":["老夫近日苦多屯，且喜来朝已立春。","但得馀殃随腊去，敢图好事逐年新。","湖山入眼风光好，亲旧论心气味真。","更若此身无疾疚，快哉天地一閒人。"]},{"t":"任漕鲁漕同谒史发运为庐阜之游恨不得偕行因成小诗二首 其二","f":"五言律诗","c":["岁事行将半，今年又有秋。","喜君将漕计，容我厕英游。","湓浦古来胜，庐山天下幽。","此行殊不恶，莫惜少迟留。"]},{"t":"任漕鲁漕同谒史发运为庐阜之游恨不得偕行因成小诗二首 其一","f":"五言律诗","c":["不向庐山久，回头五十秋。","羡君联骑去，顾我几时游。","五老想如故，二林应更幽。","无因陪后乘，神往但形留。"]},{"t":"再用前韵坚使帅凌歊之约","f":"七言律诗","c":["喜对东风玩朵云，按行知已遍淮滨。","论心我正怀良晤，乘兴公应继昔人。","采石江头天欲霁，凌歊台上物长春。","从容傥许留牙纛，看取姑溪岁事新。"]},{"t":"再用前韵奉寄","f":"七言律诗","c":["向来虽著侍臣冠，忧国曾无一日欢。","正色立朝从古少，犯颜论事似君难。","思贤会见重相得，乐圣何妨且自宽。","回首高风谁复继，凛然名节照人寒。"]},{"t":"再和","f":"七言律诗","c":["举世争披乐广天，得联契好岂徒然。","少留接武游麟阁，晚更先期到鹿田。","此日莫登扬子宅，何时能泛剡溪船。","傥容一夜陪清话，胜把陈编读十年。"]},{"t":"再和","f":"七言律诗","c":["老去光阴有几旬，到官俄见岁华新。","陡惊懒慢随年长，更觉衰残畏客频。","愧我方为牵俗士，羡君欲作独醒人。","相逢未用辞归去，且向双溪醉早春。"]},{"t":"再和","f":"七言律诗","c":["少年勤苦惜三馀，老去惟思泛五湖。","已向林间甘淡泊，更从尘外学虚无。","酒徒渐觉随年减，诗债还应隔岁逋。","强欲冥搜赓绝唱，苦无笔力似三苏。"]},{"t":"再和二首 其二","f":"七言律诗","c":["平生相见即眉开，几遣车停马首回。","窗外每怜随月到，竹边还喜过墙来。","寒香入坐如相觅，幽艳迎人欲自媒。","不负此花惟有醉，殷勤且覆掌中杯。"]},{"t":"再和二首 其一","f":"七言律诗","c":["一枝昨夜雪中开，报道江南春信回。","自与东君私有约，不须驿使寄将来。","风姿端是飞琼侣，标格宜为弄玉媒。","莫惜移尊来月下，要看疏影落金杯。"]},{"t":"再和三首 其三","f":"五言律诗","c":["忆昔干戈里，劳君远访余。","再为千里别，又是一年馀。","天末空樽酒，人生念辅车。","西湖从处好，毕竟若为居。"]},{"t":"再和三首 其二","f":"五言律诗","c":["范侯心貌古，懒与世争名。","此去穷弥壮，逢时用则行。","琴尊无限好，道义有馀荣。","末俗方奔竞，思君坐到明。"]},{"t":"再和三首 其一","f":"五言律诗","c":["不才当退缩，何况国阽危。","犹事毛锥子，欲攀丹桂枝。","人怜无好命，自笑不知时。","且尽一樽酒，高歌展两眉。"]},{"t":"再和四首 其四","f":"七言律诗","c":["新买湖头十亩园，绿阴罅里见青天。","金樱相亚枝枝袅，银杏低垂颗颗圆。","仰看乌鸢翔古木，俯窥鸥鹭戏晴川。","便须临水营台榭，要与渔樵乐暮年。"]},{"t":"再和四首 其三","f":"七言律诗","c":["卜得幽居野性便，山中风月水中天。","新栽翠竹阴虽薄，旧植青松盖已圆。","高致固难追绿野，胜游那复继斜川。","我今已得安心法，早挂衣冠不待年。"]},{"t":"再和四首 其二","f":"七言律诗","c":["归来深欲断尘缘，常拜青词密吁天。","既幸此身无玷辱，更欣尽室得团圆。","扪心只合安三径，度力那能障百川。","若也天公终见念，从今便是再生年。"]},{"t":"再和四首 其一","f":"七言律诗","c":["花枝拂眼柳垂肩，幸得身閒且乐天。","木杪夕阳当反照，草头朝露岂长圆。","兴来策杖云迷径，睡起凭栏月满川。","老矣不堪供世用，只将萧散度残年。"]},{"t":"再和前韵赠江朝宗","f":"五言律诗","c":["方欣佳客至，已寄好诗来。","玩味徒三叹，披寻欲百回。","相思愁梦断，一见笑颜开。","便欲扶藜杖，江头共探梅。"]},{"t":"再和龚帅所寄 其一","f":"七言律诗","c":["契阔经年阻曳裾，满簪华发愈萧疏。","五禽聊作林间戏，双鲤忽传江上书。","诗句方惭成间断，交情岂谓益勤渠。","开缄更诵惊人语，恍若相从听佩琚。"]},{"t":"再和龚帅所寄 其二","f":"七言律诗","c":["闻道公庭白昼閒，更无夜犬吠江关。","一时戾气俱销尽，千载淳风顿使还。","但恐赐环来北阙，不容拄笏看西山。","祇今汲直如公少，正赖忠言一犯颜。"]},{"t":"再辱九日和章连日公冗失于奉赓今日大阅偶于马上得之兼简是日座客","f":"七言律诗","c":["老子年来百念灰，尚怀月观与风台。","良辰祇恐转头过，好景还欣入眼来。","几席坐穷千里胜，轩窗高揖四山开。","公馀不厌频登眺，要伴诸君醉百回。"]},{"t":"同日和黄繁昌韵","f":"七言律诗","c":["乘闲聊复出城游，所喜相从尽胜流。","已对江山销客恨，更添花卉解人愁。","须知世事浑如梦，还念人生尽若浮。","君若更辞花下醉，问君能有几春秋。"]},{"t":"同日登青山偶作","f":"七言律诗","c":["公馀不惮陟崔嵬，三到谢公池上来。","下视众山俱培塿，俯窥尘世尽氛埃。","松生清籁醒人耳，花褪残红堕酒杯。","喜与诸君同胜赏，莫辞一醉少徘徊。"]},{"t":"有感","f":"七言律诗","c":["自度吾生不久长，老怀犹自爱风光。","春来扶杖观花急，夏到穿林看笋忙。","无限故人成鬼录，几多逐客寓他乡。","我今幸得身无事，剩向湖边醉几场。"]},{"t":"江月台","f":"七言律诗","c":["秋来江月十分明，台上凉生气倍清。","正好醉吟时自适，若为衰病日相萦。","苦无佳况人空老，数尽残更梦不成。","料想宾僚应笑我，鬓丝如此尚含情。"]},{"t":"江朝宗许重阳见过候终日竟不闻车音使人怅然因成拙句以诮之","f":"七言律诗","c":["故人平日号推诚，然诺应当作世程。","已是赏花频爽约，若为把菊又渝盟。","诗成本拟君相和，酒熟当怜我独倾。","惆怅死生犹未隔，如今先已见交情。"]},{"t":"池上近作假山引水穿石撒珠其上亦有可观因成拙句","f":"七言律诗","c":["终日尘劳困簿书，无因归泛小西湖。","且来池上看堆翠，更向峰前认撒珠。","触石有云时点缀，随风无雨自沾濡。","老夫行矣休官去，留与邦人作画图。"]},{"t":"老妻生朝为寿","f":"七言律诗","c":["人生七十古来稀，我幸君今及见之。","教得子能传素业，养成孙亦守清规。","禀生坎坷今当泰，积善初终志不移。","白首喜为林下伴，愿从今日到期颐。"]},{"t":"自京口至建康一路不见梅花慨然有作","f":"七言律诗","c":["尽日经行不见梅，竹篱茅屋漫徘徊。","无时得遣愁怀去，有底能教诗思来。","遥想故园应好在，不知今岁为谁开。","何时花下还如旧，一笑相看把酒杯。"]},{"t":"自建康路中见梅次前韵","f":"七言律诗","c":["行尽山冈喜见梅，停骖深欲少徘徊。","那知急雨连天暗，更有狂风捲地来。","无计略临花下坐，却嗟空向眼前开。","行人赖有尊中绿，遥想孤芳寄一杯。"]},{"t":"自湖上归游朱园和李相之韵二首 其二","f":"七言律诗","c":["闻道城东有故家，海棠初试万枝花。","偶来花下烧银烛，还似空中散绮霞。","园里高人全旷达，坐中骚客富文华。","新诗已就惊人句，醉墨纵横似乱鸦。"]},{"t":"自湖上归游朱园和李相之韵二首 其一","f":"七言律诗","c":["万顷湖光一镜开，几人湖上散轮蹄。","水明尽倒千岩影，沙软新成百里堤。","草际已横烟雨艇，眼前无复稻粱畦。","马侯遗迹依然在，顾我无功敢与齐。"]},{"t":"观梅偶成二首 其二","f":"七言律诗","c":["经年不见梦魂飞，依旧仙装淡薄衣。","玉骨已无尘俗气，冰姿还耐雪霜威。","携壶正欲酬清赏，策杖何妨历翠微。","莫惜对花拚剧饮，看看风雨捲春归。"]},{"t":"观梅偶成二首 其一","f":"七言律诗","c":["化工一夜报春回，雪里南枝已渐开。","不与凡条斗红紫，独将孤艳照池台。","胜游滥缀蓬山侣，高唱宁追郢客才。","多病自怜心尚在，不辞岁岁为君来。"]},{"t":"过吴门登简孚堂有感","f":"七言律诗","c":["三十年前此宦游，经从偶得驻扁舟。","回头岁月如驹隙，到眼风烟独虎丘。","无复故人论旧事，却因陈迹惹新愁。","此生未必能重到，且为斯堂更少留。"]},{"t":"过吴江题臞庵","f":"七言律诗","c":["壮岁经行今白头，未容归老复来游。","人如化鹤云间去，桥似垂虹天际浮。","风月一川无限兴，烟波万顷不胜愁。","三贤高躅何难继，犹抗尘容祇自羞。"]},{"t":"余以庚寅十月十日抵敝庐今恰三年感而有作偶成三律 其三","f":"七言律诗","c":["幸有湖边数亩园，尚堪行乐度残年。","惊鱼自合潜渊去，倦翼宁思出谷迁。","既乏仙方能却老，又无奇策可扶颠。","但知藏拙安吾分，一任人称贤不贤。"]},{"t":"余以庚寅十月十日抵敝庐今恰三年感而有作偶成三律 其二","f":"七言律诗","c":["何处风烟似我园，且将萧散乐馀年。","向来已不忧三黜，老去谁能羡九迁。","门外往还惟白足，里中游旧尽华颠。","竹林已是幽栖地，只恐风流愧七贤。"]},{"t":"余以庚寅十月十日抵敝庐今恰三年感而有作偶成三律 其一","f":"七言律诗","c":["溯自洪都返故园，今朝倒指恰三年。","举头但见松筠长，转盼那知岁月迁。","幸有青山长在眼，休嗟白发已垂颠。","此身傥未归黄壤，花下犹堪醉圣贤。"]},{"t":"余以前年五月八日到官今年又于此日去郡同僚作饯即席援笔言别","f":"七言律诗","c":["来守江山恰二年，同僚何幸得诸贤。","屡邀风月供吟笔，几度江山棹酒船。","自分衰颓今老矣，可堪离索更凄然。","青云有路平如砥，公等应须早着鞭。"]},{"t":"余年七十辄和乐天诗以自广","f":"七言律诗","c":["已是年龄及七旬，田园稍给未全贫。","儿孙初识传儒业，世俗还称作贵人。","门外湖山浑可乐，沙头鸥鹭更相亲。","莫将尘事干吾虑，已向君王乞此身。"]},{"t":"余有重阳诗岁和一篇今日偶和成二首 其二","f":"七言律诗","c":["去岁重阳解郡章，归来又复见重阳。","此身已作林泉客，今日更持萸菊觞。","正要登高穷远目，不妨拚醉浣愁肠。","佳辰若得长无事，何必乘云至帝乡。"]},{"t":"余有重阳诗岁和一篇今日偶和成二首 其一","f":"七言律诗","c":["此会从来有故常，湖山岁岁做重阳。","黄花已是铺三径，绿酒何妨举百觞。","小圃晚来堪散步，薄田秋入足充肠。","登临莫起凄凉叹，且喜成归老故乡。"]},{"t":"余既和乐天诗而喜于年及之心犹不能自已又复再和八首 其八","f":"七言律诗","c":["一年三百有馀旬，举世栖栖苦迫贫。","得享安宁七十岁，已胜衰谢万千人。","好官纵使登三事，荣养何由及二亲。","争似山间林下坐，无忧无毁足全身。"]},{"t":"余既和乐天诗而喜于年及之心犹不能自已又复再和八首 其七","f":"七言律诗","c":["忆在霜台未六旬，尝陈仕宦纵家贫。","岂容七十不纳禄，却为斗升犹牧人。","年齿幸吾今已及，官曹从此不应亲。","愿天许遂终焉志，养此疏慵老大身。"]},{"t":"余既和乐天诗而喜于年及之心犹不能自已又复再和八首 其六","f":"七言律诗","c":["故园春到已三旬，满目繁华未觉贫。","年老得逢无事日，心闲不类有官人。","戴花休管头无那，酌酒何妨手自亲。","七十人生从古少，安知来岁有吾身。"]},{"t":"余既和乐天诗而喜于年及之心犹不能自已又复再和八首 其五","f":"七言律诗","c":["新岁妻孥庆七旬，遍赒邻里及孤贫。","高年满座有醉客，丐者塞涂无馁人。","平日要同人喜乐，此时宁间物疏亲。","馀生自度浑能几，讵可徒劳负此身。"]},{"t":"余既和乐天诗而喜于年及之心犹不能自已又复再和八首 其四","f":"七言律诗","c":["先子春秋仅八旬，一生多难只安贫。","岂期有子登清禁，亦复如今作老人。","共羡浮荣光故里，自惭实德忝吾亲。","从前万事皆踰分，只合归休保此身。"]},{"t":"余既和乐天诗而喜于年及之心犹不能自已又复再和八首 其三","f":"七言律诗","c":["封章上达已经旬，所乞原非为贱贫。","七秩自知非久客，一心只欲作闲人。","虽惭绿鬓朱颜改，却喜清泉白石亲。","荣辱是非都不问，尊前且乐自由身。"]},{"t":"余既和乐天诗而喜于年及之心犹不能自已又复再和八首 其二","f":"七言律诗","c":["乞得行年到七旬，归田不问富和贫。","初非洁己为高士，但欲颐心如古人。","每对青山常意适，才逢白叟便情亲。","静中百念俱灰灭，识破浮生梦幻身。"]},{"t":"余既和乐天诗而喜于年及之心犹不能自已又复再和八首 其一","f":"七言律诗","c":["坐阅流年已七旬，从前忧道不忧贫。","肯教世指为痴汉，只愿乡称作善人。","老去固应忘物我，归来岂是负君亲。","尝闻知进须知退，庶得终全不辱身。"]},{"t":"初冬山居即事十首 其十","f":"五言律诗","c":["田宅虽无几，琴书幸有馀。","不妨临水赋，况是背山居。","适意真为乐，浮名总是虚。","前贤犹若此，我辈欲何如。"]},{"t":"初冬山居即事十首 其九","f":"五言律诗","c":["搔首寒窗下，荒山草树迷。","鸟声喧昼寂，雁阵接天低。","更欲开三径，终当把一犁。","此心非傲世，揣分合幽栖。"]},{"t":"初冬山居即事十首 其八","f":"五言律诗","c":["年去惊人老，坐来忘夜深。","未能成一事，何敢废分阴。","灯尽添残烛，山寒拥败衾。","幸无尘俗虑，聊遂读书心。"]},{"t":"初冬山居即事十首 其七","f":"五言律诗","c":["久出畏人事，端来避世纷。","山光闲里见，樵唱静中闻。","茗碗晴翻雪，香炉晓吐云。","已应空百念，勿复叹离群。"]},{"t":"初冬山居即事十首 其六","f":"五言律诗","c":["本是山中客，胡为作远游。","风波惊脱险，岩谷喜寻幽。","纸帐寒来煖，僧蔬饱即休。","百年如一梦，此外复何求。"]},{"t":"初冬山居即事十首 其五","f":"五言律诗","c":["节物随时变，斜阳一望中。","暮云重叠碧，远树浅深红。","菊色滋寒露，芦花荡晚风。","一樽谁与共，独立意无穷。"]},{"t":"初冬山居即事十首 其四","f":"五言律诗","c":["自笑谋生拙，空惊岁月除。","年衰惟藉药，发少不禁梳。","尽日扃蓬户，无人过草庐。","晚来闲策杖，缓步当柴车。"]},{"t":"初冬山居即事十首 其三","f":"五言律诗","c":["归来非计失，事少得心宽。","村落年方稔，庭闱病复安。","诗当随景赋，酒莫放杯乾。","插架书还在，仍容子细看。"]},{"t":"初冬山居即事十首 其二","f":"五言律诗","c":["屋角营书室，新成八九椽。","开林延爱日，甃石截流泉。","山近岚光逼，窗疏月色穿。","寒梅何日吐，我欲醉花前。"]},{"t":"初冬山居即事十首 其一","f":"五言律诗","c":["我爱山居好，冬来惬野情。","檐前朝日暖，谷口暮云横。","柏子当轩堕，蕉花傍槛生。","自堪安朴拙，何苦慕尘缨。"]},{"t":"初夏登城上有感","f":"七言律诗","c":["来守孤城忽两期，可堪登眺又斜晖。","经春不见流莺语，终日唯看乳燕飞。","风舞新荷青袅袅，烟笼细柳绿依依。","此邦纵美非吾土，莫怪山翁只念归。"]},{"t":"寿元伯母太夫人八秩","f":"七言律诗","c":["七十康强自古稀，年登八秩有谁宜。","寿钟贤母人难及，庆袭佳儿世共知。","荣养已为人子范，清规还作女流师。","綵衣更戏兰阶下，遥想慈颜笑解颐。"]},{"t":"志道相见和前韵","f":"七言律诗","c":["每忆湖山动老怀，今朝始作故乡回。","正惭行李匆匆去，忽报轺车得得来。","幸对清谈挥玉麈，肯辞痛饮倒金杯。","我归已遂终焉计，何日重逢笑口开。"]},{"t":"怀归有作","f":"七言律诗","c":["一病兼旬百不禁，愈牵归梦绕家林。","向来岂有功名念，此去断无人我心。","但愿天怜将就木，许从人欲便投簪。","若蒙不靳清闲福，尚惜馀年尽寸阴。"]},{"t":"怀梁丈陈丈","f":"七言律诗","c":["不见高标动浃旬，寸心如渴欲生尘。","春深渐觉梅花老，风暖还惊柳色新。","对景想题诗句满，开怀应把酒杯频。","扁舟前后空相望，安得从容笑语亲。"]},{"t":"李子仪喜津改秩作诗相庆因次韵 其二","f":"七言律诗","c":["有屋依山复面湖，幽栖试问有谁如。","门前更种千竿竹，堂上还堆万卷书。","每恨暮年方卜筑，岂知今日得安居。","鲤庭况有新桃李，莫惜时来长者车。"]},{"t":"李子仪喜津改秩作诗相庆因次韵 其一","f":"七言律诗","c":["懒复从人问里评，纵今得誉亦虚声。","有儿第使传儒业，改秩何期冒宠荣。","敢望芝兰如谢氏，但亲松菊学渊明。","烦君慰藉来佳句，读罢欣然酒一倾。"]},{"t":"李仓子长按行偶成四韵奉呈 其一","f":"七言律诗","c":["强把州麾楚水东，星轺临按偶相逢。","平居已是同闾里，岁晚还来托部封。","千里江山多契阔，一樽风月且从容。","我将投绂林泉去，拭目公归侍九重。"]},{"t":"泛舟归自郡中舟中偶成 其一","f":"五言律诗","c":["寒流清更浅，短棹去仍来。","山色侵书帙，波光映酒杯。","龟鱼应旧识，鸥鹭莫相猜。","全胜山阴路，空船载月回。"]},{"t":"泛舟归自郡中舟中偶成 其二","f":"五言律诗","c":["薄日烘云影，轻风溅浪花。","数峰排绝岸，一雁落平沙。","冉冉寒生袖，悠悠梦到家。","前村谁有酒，试遣小童赊。"]},{"t":"贡院落成郡庠诸生毕集因作诗以勉之","f":"七言律诗","c":["多士如林古豫章，不应较艺寓僧房。","一朝尽辟荆榛地，万础俄新翰墨场。","文笔要同孤塔耸，词源宜与两湖长。","会看从此飞鸣去，九万鹏程未易量。"]},{"t":"远老自和前诗再寄复次韵","f":"七言律诗","c":["雪到梅开恰欲漫，扶藜得得绕湖山。","折将冷蕊疏枝去，浸在明窗净几间。","一见已堪资琢句，细看还足助怡颜。","只愁冰艳相侵逼，映得衰翁鬓愈斑。"]},{"t":"远老惠雪中观梅诗次韵以谢","f":"七言律诗","c":["山头飞雪已漫漫，云散须臾复见山。","踏雪不辞来野外，爱梅须遍走林间。","为怜孤艳思经目，拟索疏枝笑解颜。","师肯相过宜及早，预愁花点绿苔斑。"]},{"t":"陈时中法台得郡而归喜而成诗","f":"七言律诗","c":["去岁秋风话别离，今秋俄报有归期。","自应冠豸登三院，何遽凭熊把一麾。","治行伫为千里最，才猷已是九重知。","莫辞小憩留仙隐，伴我花前倒玉卮。"]},{"t":"到双胜匆匆不及款舟中成小诗寄良器兼简杨宰","f":"七言律诗","c":["海滨何处足春风，尽在王孙小圃中。","雨洗山光供几席，日移花影上帘栊。","扁舟回首烟波隔，尊酒何时笑语同。","若对扬雄赏幽胜，杯行应亦话衰翁。"]},{"t":"和人见寄","f":"七言律诗","c":["高义如君举世无，贤关十载会琴书。","匆匆边马来时别，郁郁乱山深处居。","天外风尘仍断绝，人间豪杰正萧疏。","何时樽酒论文去，千里相思寄望舒。"]},{"t":"和十五侄见寄","f":"七言律诗","c":["草庐高卧几经春，被褐深藏席上珍。","已自闭门甘澹泊，不妨琢句自清新。","我惭老去同流俗，日念归来作野人。","此后埙篪酬唱罢，因风见寄莫辞频。"]},{"t":"和十五侄韵","f":"七言律诗","c":["无补公家祇主臣，但思高卧故山云。","宦游耻蠹太仓粟，归去贪羹碧涧芹。","喜得醇醪堪饮客，还惊妙句更超群。","速来共为梅花醉，趁取枝头香正芬。"]},{"t":"和子仪同赏荷花","f":"七言律诗","c":["晚凉领客泛涟漪，境胜形容颇费诗。","人自红莲丛里过，舟从绿柳岸边移。","兴来滞思俄然豁，坐久烦襟顿觉披。","佳客要须拚一醉，莫辜风细月明时。"]},{"t":"和天予即席咏岩桂","f":"七言律诗","c":["衰病无悰日日加，喜君来自帝王家。","素娥正驾一轮玉，老桂方开双树花。","置酒虽欣陪重客，侑樽还愧乏名娃。","莫辞今夕如泥醉，须念明朝各一涯。"]},{"t":"和天予孺子亭三首 其三","f":"七言律诗","c":["我来湖上访前贤，正值清秋欲暮天。","十顷败荷攲浅水，千章古木锁寒烟。","遍寻陈迹俱亡矣，独立幽亭祇黯然。","清德照人增我愧，暮年独未返林泉。"]},{"t":"和天予孺子亭三首 其二","f":"七言律诗","c":["东汉诸公孰最贤，南州高士独推先。","蒲轮徒枉当年聘，尘榻从教尽日悬。","吾道固应天未丧，此时争奈木将颠。","栖栖尔辈成何事，那似清风万古传。"]},{"t":"和天予孺子亭三首 其一","f":"七言律诗","c":["南州高士务躬行，不事王侯祇力耕。","西岭已如刚节峻，东湖还似古心清。","正惭老拙非良牧，安有仁恩及庶氓。","若也当年能逐迹，他时容或可齐名。"]},{"t":"和尹少稷席上韵","f":"五言律诗","c":["每恨千山隔，俄欣一日同。","交游非比众，人物少如公。","正欲扶公道，端期振此风。","不须深退避，风雨要帡幪。"]},{"t":"和方叔载留别","f":"七言律诗","c":["临别殷勤赠我诗，一披何喜得如之。","怪来笔下能高妙，元是胸中自崛奇。","长恨顷时才一面，方欣今岁展双眉。","明年莫负论文约，要向新元副所期。"]},{"t":"和方叔载读小集","f":"七言律诗","c":["江城留滞两经年，强把诗篇拟昔贤。","岂有高歌翻白雪，祇凭短句问青天。","优人献伎徒供笑，丑妇添装岂解妍。","君欲学诗须学古，不应读此向窗前。"]},{"t":"和王夷仲至日有感","f":"七言律诗","c":["葭灰管里气初浮，阳长阴消不自谋。","吾道穷耶当复泰，此身老矣不禁愁。","得闲正好寻诗社，乘兴何妨上钓舟。","拟待梅开同胜赏，且宽归兴少迟留。"]},{"t":"和王夷仲雪中见贻","f":"七言律诗","c":["岁晚端居寂寞滨，雪花零乱更愁人。","捲帘已觉青山老，入座仍添白发新。","写景自怜佳句少，论交还喜宿心亲。","来诗况复清如雪，想见吟成泣鬼神。"]},{"t":"和王夷仲韵","f":"七言律诗","c":["洒落胸襟有古风，日临清泚面巃嵷。","不堪世路千重险，直与溪流万折东。","刮眼相看言有味，倾怀一笑兴无穷。","何时同访连樯老，快意觥船一棹空。"]},{"t":"和王夷仲韵","f":"五言律诗","c":["故人声气合，交契久弥深。","不弃荒村陋，来分古木阴。","意倾陈笃论，兴发出高吟。","岂料逃空谷，犹闻正始音。"]},{"t":"和王龟龄待制贡院落成二首 其二","f":"七言律诗","c":["主盟湖学属何人，赖有公来为作新。","士俗似闻衰也久，文场今见美哉轮。","挈还旧观人争睹，赋就新诗笔有神。","苕霅儒风从此振，文翁端恐是前身。"]},{"t":"和王龟龄待制贡院落成二首 其一","f":"七言律诗","c":["扁舟犹记拂洲蘋，转眼年华几度新。","愧我今成双白鬓，喜君来驾两朱轮。","一时令下从如水，千里威行敬若神。","拟访旧游观盛事，一官何苦绊吾身。"]},{"t":"和王致君见寄望海亭诗","f":"七言律诗","c":["领客闲登木杪亭，坐来四面对峥嵘。","野田散漫高低绿，湖水瀰茫远近清。","览胜喜穷千里目，放怀笑引百壶倾。","酒阑未用忙归去，更看亭前海月明。"]},{"t":"和王瞻叔泉字韵","f":"七言律诗","c":["暮年亦复侍甘泉，每对青铜只自怜。","宁忍忧疑探虎穴，且将得失付鱼筌。","归来但欲无身累，老去那能徇世缘。","若得优游全晚节，从人唤作地行仙。"]},{"t":"和世同见怀","f":"七言律诗","c":["君去经春未得还，老夫幽恨满春山。","海棠花过乖同赏，杨柳阴成阻共攀。","对月有谁陪笑傲，临流惟影伴清閒。","何时策杖来过我，把酒论文一解颜。"]},{"t":"和叶先生见寄","f":"七言律诗","c":["春到山城花木深，兴来谁与共登临。","空惊节物催人老，强对芳菲索酒斟。","已喜筠筒先见寄，更闻藜杖欲相寻。","劝君未用忙归去，要向樽前话寸心。"]},{"t":"和叶先生韵 其二","f":"七言律诗","c":["杯酒忘怀不计巡，少年行乐肯输人。","年来性复便疏懒，老去谁能浪苦辛。","春暖园林花放早，月长庭院燕来频。","物华正尔撩诗思，况得诗翁好句新。"]},{"t":"和叶先生韵 其一","f":"七言律诗","c":["三分春色一分强，风雨忧愁莫见妨。","何幸山城官事少，且看溪路野花香。","丝丝嫩绿垂流水，片片飞红逐去樯。","一日要须拚一醉，百年能醉几千场。"]},{"t":"和叶性之喜雨","f":"七言律诗","c":["去岁饥荒特异常，那知今日便丰穰。","田畴雨足经时润，院宇风生着处凉。","老去我方辞五斗，秋来谁解积千仓。","从今闾里无艰食，会见家家酒熟香。"]},{"t":"和四二侄用林道叟见寄字韵","f":"七言律诗","c":["华发萧萧日夜疏，奔驰不止欲何如。","得抛印绶心方适，归见湖山气始舒。","世事转头如蝶梦，人生到此似蘧庐。","我今已作终焉计，却悔当年赴鹤书。"]},{"t":"和四哥钱塘思归韵","f":"七言律诗","c":["郁郁羁怀久欲东，故园何日割蒿蓬。","可堪世路尘缨缚，却使云山蕙帐空。","待价深藏非左计，汗颜为斲岂良工。","须知吕望严陵辈，亦是沧浪一钓翁。"]},{"t":"和左达功春日见寄二首 其二","f":"五言律诗","c":["万方多难日，千里故人心。","酒社知谁在，诗盟阻重寻。","莺啼空日暮，花落又春深。","我去惭无计，何年许见临。"]},{"t":"和左达功春日见寄二首 其一","f":"五言律诗","c":["良觌弥年阻，相思入梦迷。","性疏仍寡合，世乱且幽栖。","极目苍山北，伤心白水西。","书空愁坐处，还是暮云低。"]},{"t":"和左达功春日即事二首 其二","f":"五言律诗","c":["春色还如旧，吾生愧此心。","功名嗟晼晚，时序忆追寻。","万国豺狼满，重城草木深。","西湖真赏处，空想旧登临。"]},{"t":"和左达功春日即事二首 其一","f":"五言律诗","c":["世途虽反侧，春草自萋迷。","独树花仍发，何枝鹊可栖。","犬羊终逐北，貔虎未征西。","回首长安路，茫茫日欲低。"]},{"t":"和田伯清见寄 其二","f":"七言律诗","c":["落笔摛辞烂有章，故应往岁擅文场。","身登霄汉声猷著，兴寄湖山气味长。","无计盍簪同把酒，尚怀扫地对焚香。","依然日暮碧云合，相望回头各一方。"]},{"t":"和田伯清见寄 其一","f":"七言律诗","c":["可叹人生有限身，终朝长是困嚣尘。","向来每愧为人役，今日方能保我真。","幸有一丘堪避俗，何妨百岁作閒人。","更烦妙句相褒借，顿觉柴门暖似春。"]},{"t":"和任漕开宴值雨","f":"七言律诗","c":["正是千花万卉开，一时景物亦佳哉。","良辰已幸陪龙节，盛宴仍容饫豹胎。","虽喜风光环几席，其如烟雨暗池台。","明朝天宇应澄霁，尚拟寻芳一再来。"]},{"t":"和任漕罗溪道中韵","f":"五言律诗","c":["揽辔驰原隰，行行四牡骄。","风烟方入眼，雷雨忽连宵。","官事终期了，征途岂惮遥。","经旬怀笑语，嗟我亦何聊。"]},{"t":"和任漕韵","f":"五言律诗","c":["耆英持漕节，一稔百无忧。","心计唯丰国，文移罕到州。","泽流千嶂雨，效见万家秋。","早晚趋严召，雍容侍冕旒。"]},{"t":"和刘与几悟昔","f":"七言律诗","c":["先生岂是傲当时，知向名场早识机。","扰扰半生蝴蝶梦，休休今日绿蓑衣。","笔端信有江山助，醉里从教日月飞。","应笑蘧生回首晚，才知四十九年非。"]},{"t":"和刘正夫见寄 其二","f":"七言律诗","c":["已是龙钟七十人，故应告老上章频。","九重垂念如慈父，一旦容归作幸民。","今我可怜非故我，此身才喜是吾身。","花前幸有尊中醁，且醉湖山几度春。"]},{"t":"和刘正夫见寄 其一","f":"七言律诗","c":["揽辔澄清慕古人，观风问俗按行频。","振荒已视饥由己，畜水犹思利及民。","美意共推君体国，高怀还喜我抽身。","名章下逮情何厚，和气薰然暖似春。"]},{"t":"和朱文卿见赠","f":"七言律诗","c":["簿书终日叹徒劳，俄喜相看有故交。","抱道尚稽怀印绶，安贫还不厌衡茅。","草庐谁识真龙卧，阿阁行看彩凤巢。","归去不妨深闭户，静听修竹晚风敲。"]},{"t":"和朱文卿春雪韵","f":"七言律诗","c":["春来何事尚凝严，一夜空庭霰雪兼。","坐久罗衣惊顿薄，更阑杯酒觉频添。","旋消疏滴檐间雨，更看平堆地上盐。","谁道东风回暖律，韬霞掩日不容觇。"]},{"t":"和朱文卿落解后书怀","f":"七言律诗","c":["先生英气欲横秋，唾手功名岂待求。","共指层霄看展翼，谁知平地亦沉舟。","箦中宰相宁嫌辱，胯下将军未足羞。","有志会须腾踏去，莫将富贵羡王侯。"]},{"t":"和朱世同见寄","f":"七言律诗","c":["门外青山玉作堆，山前一水更萦回。","归来虽喜风烟好，老去还惊岁月催。","不见故人增寂寞，尚怀往日共徘徊。","何时轩盖重相过，伴我花前醉百杯。"]},{"t":"和朱世同咏梅","f":"七言律诗","c":["竹篱茅舍旧同居，不见冰姿恰岁馀。","别后有谁亲几席，朝来忽喜映阶除。","雪中有酒宜相就，月下无人肯自疏。","端与岁寒长有约，不须青帝更吹嘘。"]},{"t":"和朱世同夜坐待月","f":"七言律诗","c":["新凉初入我庭中，满座清风孰与同。","已喜故人来聚首，那堪明月更当空。","满倾浊酒休辞醉，剩作新诗莫讳穷。","屈指如今诗酒社，有谁胸次得如公。"]},{"t":"和朱世同韵 其一","f":"七言律诗","c":["聊向空山避世喧，数椽茅屋锁苔钱。","怕逢俗客慵开户，欣慕前贤愿执鞭。","已见二毛真老矣，幸存三径盍终焉。","细思万计惟閒好，敢为浮名误百年。"]},{"t":"和朱世同韵 其二","f":"七言律诗","c":["幽栖终日断经过，坐阅残编眼欲花。","道在固应甘淡薄，心閒尤觉厌纷华。","正惭我老无佳思，颇羡君诗似作家。","拙恶岂能赓妙句，临风吟咏祇咨嗟。"]},{"t":"和朱世同韵 其三","f":"七言律诗","c":["道义谁人似乃翁，有儿如子岂忧穷。","自应便享千钟养，不谓今犹四壁空。","好遣江山归笔下，莫将荆棘置胸中。","诗书傥不辞勤苦，衣绣何难继祖风。"]},{"t":"和朱世同韵二首 其二","f":"七言律诗","c":["已归林下得从容，还喜时和与岁丰。","好景尽归诗句里，閒愁俱付酒杯中。","腊残惟愿呈三白，春去从教落万红。","亲旧自今休问位，只须唤我作吴公。"]},{"t":"和朱世同韵二首 其一","f":"七言律诗","c":["立朝初不愧廷臣，晚节胡为苦乞身。","自度济时无远略，不如辞禄作閒人。","林间幸已安禅榻，湖上何妨掷钓纶。","若也故人能过我，尚堪共醉瓮头春。"]},{"t":"和朱守有待亭","f":"七言律诗","c":["使君敛惠抚吾乡，物阜年丰特异常。","已向湖中同众乐，更来山上发天藏。","登临缅想高怀适，赋咏悬知雅兴长。","独恨杜门方屏缩，莫窥佳致望馀光。"]},{"t":"和江朝宗韵奉寄","f":"七言律诗","c":["休言簿领尚沉迷，器业如公岂久稽。","不见自怜心若失，相从还记手同携。","飞黄正欲驰长坂，倦翼方欣返故栖。","出处不同空怅望，何时来过武陵溪。"]},{"t":"和池州陈教授韵二首 其二","f":"七言律诗","c":["平时野性爱吟诗，一字长惭未得师。","妙句既容窥格律，良辰更喜觌光仪。","绛帷暂且留三楚，丹陛行将命一夔。","莫为浮荣求速化，功名到底属男儿。"]},{"t":"和池州陈教授韵二首 其一","f":"七言律诗","c":["人物今谁似此郎，合居严近赞垂裳。","未将事业先诸老，且把文章变一方。","今日杏坛风似鲁，向来铁砚志如桑。","会看奋迅为时用，展尽胸中计策长。"]},{"t":"和许守重阳出城韵","f":"七言律诗","c":["晓从千骑越重闉，轧轧篮舆渡古津。","万叠青山烟漠漠，一溪寒水石粼粼。","笑携红袖寻莲社，醉折黄花上葛巾。","此会从今成故事，他年应记座中人。"]},{"t":"和许守野亭登眺","f":"七言律诗","c":["夫君自合代王言，暂寓空斋八九椽。","尽日清谈挥麈尾，闭门危坐爇龙涎。","诗囊遣兴随时赋，茗碗袪魔对客煎。","看即除书催入觐，得閒登眺且欣然。"]},{"t":"和许守喜雨韵 其二","f":"七言律诗","c":["千里焦枯顿郁苍，邦人宁复虑年荒。","大田一雨浑沾足，邻壤群偷更伏藏。","治郡羡君端有术，救民愧我独无方。","夜来复诵新诗句，叹赏徘徊月转廊。"]},{"t":"和许守喜雨韵 其一","f":"七言律诗","c":["使君盛德格皇天，奔走群龙雨霈然。","坐使槁苗成茂实，潜将丰岁换凶年。","荷锄野老欣嘉应，抱瓮田夫得晏眠。","拟倩乐工弦盛事，山城那得有师涓。"]},{"t":"和许守喜雪韵","f":"七言律诗","c":["冻云垂地木停号，六出飞花遍九皋。","已见随车翻缟带，还疑纵猎散风毛。","幽人乘兴空回棹，公子无言独拥袍。","顾我年来诗思涩，强吟冰柱愧才高。"]},{"t":"和许守韵","f":"七言律诗","c":["台阁如公盍见收，尚淹外补为民忧。","身为邦国三年计，心在江湖万里秋。","乘兴举杯还对月，得閒搜句或临流。","平生恨不逢名士，岂谓年来遂此谋。"]},{"t":"和严倅觅碧香","f":"七言律诗","c":["不劳斋戒绝膻荤，闻已潜通妙众门。","此道能明从古少，今朝正要与君论。","十年未免忧茅塞，一诣终期破枣昏。","纵有香醪堪寄远，何如相对倒清樽。"]},{"t":"和何倅与林大任韵二首 其二","f":"五言律诗","c":["久欲寻高隐，今朝信马行。","闲看花上蝶，静听柳间莺。","披豁尘襟尽，从容乐事并。","醉来犹有恨，未许见倾城。"]},{"t":"和何倅与林大任韵二首 其一","f":"五言律诗","c":["迟日郊原好，杖藜春色随。","此行端不恶，对酒醉何辞。","竹外名花发，檐间野鸟窥。","晚来登阁望，山水更幽奇。"]},{"t":"和张君美韵二首 其二","f":"五言律诗","c":["风尘环四海，烟水绕孤村。","涉世曾无味，思君更断魂。","区区何面目，苒苒且朝昏。","此意凭谁语，悠然付酒樽。"]},{"t":"和张君美韵二首 其一","f":"五言律诗","c":["志大空忧国，途穷欲问天。","功名羞短褐，蹭蹬惜流年。","死友留天末，生涯寄海边。","相逢是何日，回首重依然。"]},{"t":"和志道送行韵","f":"七言律诗","c":["圣君图治事如何，但见风云气象和。","公似一夔奚翅足，我如乘雁岂加多。","西郊索索飘黄叶，南浦鳞鳞起绿波。","今日邮亭休恨别，行看麻制草銮坡。"]},{"t":"和李子仪到山居","f":"七言律诗","c":["接得新诗喜有馀，诗中字字说山居。","固知还舍方为乐，亦悟浮名总是虚。","无计林间闲放鹤，何时湖上静观鱼。","我心万事都无累，祇欠归来得自如。"]},{"t":"和李子仪韵四首 其四","f":"五言律诗","c":["夜向茅茨宿，晨兴矫首看。","远山俱有雪，小店更多寒。","客路虽云恶，儿曹幸已安。","不妨频小憩，时引一杯乾。"]},{"t":"和李子仪韵四首 其三","f":"五言律诗","c":["我自吾儿病，匆匆去若逃。","天寒霜似雪，山险石如刀。","已得平安信，宁辞往复劳。","故园归去也，醉里甚游遨。"]},{"t":"和李子仪韵四首 其二","f":"五言律诗","c":["我已成衰谢，传家在此儿。","俄然闻感疾，至欲别呼医。","愁绪浑无奈，忧心祇自知。","如今安乐也，有酒任盈卮。"]},{"t":"和李子仪韵四首 其一","f":"五言律诗","c":["甚矣吾儿病，求安欲吁天。","忧心千里切，喜信一朝传。","远胜开金穴，浑如得宝鞭。","若非天相我，今日岂能然。"]},{"t":"和李光祖 其二","f":"七言律诗","c":["老去深悲宠辱惊，归来胸次渺寰瀛。","登山临水随宜坐，问柳寻花信意行。","境胜已勾诗兴动，身閒还引道心生。","亲知满眼如君少，何不时来共一觥。"]},{"t":"和李光祖 其一","f":"七言律诗","c":["英才端合在星躔，不谓淹回阅岁年。","却向山中亲白石，更来涧下濯清泉。","高情虽似秋云淡，丽句还如蜀锦鲜。","怪得了无尘俗气，家风元是谪来仙。"]},{"t":"和李光祖二首 其二","f":"七言律诗","c":["天资洒落更瑰奇，何患诸公不己知。","运蹇尚须资汲引，时来宁复藉维持。","家声况是钧公裔，文采还高幼妇碑。","大器成时须在晚，如君方壮未为迟。"]},{"t":"和李光祖二首 其一","f":"七言律诗","c":["漏残休更问铜壶，自视平生分已踰。","每叹奔驰非得计，只知静退是良图。","耽诗况味今虽在，爱酒情怀近已无。","诏比二疏吾岂敢，或言出处亦相符。"]},{"t":"和李相之劝农","f":"词","c":["忧民无语对东君，一雨霶?慰望云。","宣化但期施实惠，劝耕宁复事虚文。","已看野老扶藜去，应有幽人植杖耘。","千里农桑知帝力，自惭滥把竹符分。"]},{"t":"和杨元明雪中见赠","f":"七言律诗","c":["为别多年不记旬，雪中闻到喜难陈。","尚稽良会心如渴，频展新诗手欲皴。","和寡莫追歌郢客，兴来还愧泛溪人。","要须早了官中事，趁取元宵作好春。"]},{"t":"和杨季恪景疏希白二首 其二","f":"七言律诗","c":["人讥居士老来迂，与世依违总不符。","虽似子牟怀魏阙，却同居易学浮屠。","锄荒只欲开三径，适意宁论泛五湖。","胸次更无尘一点，且同高士话虚无。"]},{"t":"和杨季恪景疏希白二首 其一","f":"七言律诗","c":["二疏高躅耸簪绅，寂寞无人继后尘。","一代风流虽已远，千年名德镇如新。","幸抛印绶归空谷，得与湖山作好春。","若较前贤那可并，却惭温诏下严宸。"]},{"t":"和沈子寿见寄","f":"七言律诗","c":["心地荒芜旷几春，朅来邂逅共耕耘。","交情正喜清如水，归兴那知去似云。","百首漫劳频寄远，一樽终拟再论文。","胡为竟尔乖前约，寂寞车音杳不闻。"]},{"t":"和沈先觉韵","f":"七言律诗","c":["枉度浮生八十春，休谈天数与人伦。","长贫已是难糊口，久病那堪更累身。","独把新诗娱晚景，谁将灵剂起痿人。","若教得酒时时醉，醉里高吟尚绝尘。"]},{"t":"和远老见怀","f":"七言律诗","c":["老去光阴能几何，祇求适意不求多。","消除旧恨凭三盏，断送馀生付一蓑。","风月情怀虽已灭，渔樵伴侣尚相过。","师来好趁荷花盛，我欲同游击棹歌。"]},{"t":"和远老韵","f":"七言律诗","c":["野性平时酷爱山，年来何幸得休官。","情知轩冕生无益，身在林泉死亦安。","已免出门频应接，尚贪散策纵游观。","得师妙语相开发，始觉浮华不足看。"]},{"t":"和陈义卿","f":"七言律诗","c":["自顾迂疏不入时，朅来此地亦何为。","游从断绝凭谁语，踪迹飘零祇自知。","方喜朋簪今复合，却惭酒盏但空持。","何时得遂归休去，把手临流共赋诗。"]},{"t":"和陈天予见寄真字韵","f":"七言律诗","c":["前贤惟有太丘真，岂谓于今见后身。","虽是一时为逐客，不妨千古作全人。","自从别后心如渴，却喜诗来句绝尘。","无计复陪花下醉，对花只觉倍伤春。"]},{"t":"和陈天予冠字韵","f":"七言律诗","c":["已是头童懒整冠，尊前犹欲强追欢。","浮生得满七旬少，乐事能并四者难。","闲去稍知心地适，兴来殊觉醉乡宽。","入朝更诵公诗句，两腋风生盛暑寒。"]},{"t":"和陈宗师","f":"五言律诗","c":["昨幸朋簪盍，还惊客袂分。","相望千里月，独占一溪云。","高论无由款，新诗忽得闻。","羡君岩穴下，清坐绝埃氛。"]},{"t":"和陈泽民见寄 其二","f":"七言律诗","c":["应喜衰翁得挂冠，裁成妙语鼎来颁。","清如水上看修竹，秀似云中见远山。","已播政声来阙下，更传诗句满人间。","祇疑自此飞腾去，未许归来伴我闲。"]},{"t":"和陈泽民见寄三首 其三","f":"七言律诗","c":["不学群儿事诡随，世途虽险此心夷。","人生富贵谁无分，男子功名自有时。","好称良辰聊适意，莫因末路辄兴悲。","山寒已有梅花放，想见寻梅日有诗。"]},{"t":"和陈泽民见寄三首 其二","f":"七言律诗","c":["青衫晚得自蟾宫，簿领虽卑道自隆。","不为小官忘大计，要从旧学著新功。","忽来书劄情何厚，细读诗篇句更雄。","还忆去年相聚日，风前月下酒频中。"]},{"t":"和陈泽民见寄三首 其一","f":"七言律诗","c":["平生懒病苦难医，长为家山咏式微。","投老但思抛世网，非才安敢近天威。","不堪人事来如织，况复年华去若飞。","胸次万端谁与语，何时玉麈对君挥。"]},{"t":"和陈泽民即事二首 其二","f":"七言律诗","c":["萧条古寺野僧残，聊与僧俱住翠峦。","树影绕帘春昼静，水晶摇屋暮天寒。","固知书剑不嫌冷，却恨杯盘未尽欢。","当念老人衰已久，外虽强健实中乾。"]},{"t":"和陈泽民即事二首 其一","f":"七言律诗","c":["鸡声催晓梦惊残，喜得归来卧碧峦。","已是人间三月暮，尚馀枕上五更寒。","心安靖退虽无事，身觉衰颓亦鲜欢。","赖有故人时会面，开颜一笑酒杯乾。"]},{"t":"和陈泽民咏岩桂","f":"七言律诗","c":["我家千树正芬芳，不见羁怀已倍伤。","岂谓幽姿怜索寞，亦来孤馆伴凄凉。","追寻尚想年时侣，披拂还同故里香。","花下光阴能有几，若为飘泊向江乡。"]},{"t":"和陈泽民韵","f":"七言律诗","c":["雨歇云收天意回，放教明月下天来。","为怜病守怀三径，故遣姮娥荐一杯。","坐上宾僚方共集，城头更漏莫相催。","来年此夕知谁在，对月何妨笑口开。"]},{"t":"和孟世功二首 其二","f":"七言律诗","c":["不见风标六岁馀，閒中应是乐琴书。","逢辰自合膺殊选，遁世何妨且隐居。","已爱新诗如沈谢，更听高论似严徐。","时来会有腾骧日，未许傍人笑问疏。"]},{"t":"和孟世功二首 其一","f":"七言律诗","c":["老大疏慵一腐儒，长年离索与谁俱。","杜门有意修黄老，开卷无心诵典谟。","不是穿林寻鹤鹿，即来临水伴龟鱼。","故人今日如君少，乘兴还能过我无。"]},{"t":"和孟世功秋日吴江见寄","f":"七言律诗","c":["扁舟西去气凌云，坐看鱼龙跃浪纹。","风起白蘋初日晚，霜彫红叶欲秋分。","忘机鸥鹭情相狎，入笔江山句不群。","正恐功名来追逐，烟波深处未留君。"]},{"t":"和林徽之见寄","f":"七言律诗","c":["涉世无堪足乱离，萧萧风雨一声鸡。","故人别后乾坤窄，三径归来草木迷。","黄鸟翩翻思出谷，老龙头角尚蟠泥。","一尊浊酒无人共，又是悲吟到日西。"]},{"t":"和泽民二首 其二","f":"七言律诗","c":["欲绍家声每自鞭，肯同流俗饮贪泉。","已将止足安心地，更把吟哦乐性天。","笑日桃花将献媚，先春梅蕊欲争妍。","人生会合真难遇，幸有杯觞且共传。"]},{"t":"和泽民二首 其一","f":"七言律诗","c":["归心已动不容留，多谢君恩许退休。","虽喜溪山归似旧，却惊岁月去如流。","门前已是开三径，湖上何妨具一舟。","莫道此时无伴侣，得公足可共遨游。"]},{"t":"和泽民求海棠","f":"七言律诗","c":["君是诗中老作家，笑将丽句换名花。","花因诗去情非浅，诗为花来语更嘉。","须好栽培承雨露，莫令憔悴困尘沙。","他年烂漫如西蜀，我欲从君看绮霞。"]},{"t":"和泽民送春 其二","f":"七言律诗","c":["不堪岁岁送青春，消黯浑如失所亲。","短句吟成犹恨别，清樽买尽不辞贫。","兴来直欲游三岛，老去何由驻二轮。","赖有君能知我意，肯来同作送春人。"]},{"t":"和泽民送春 其一","f":"七言律诗","c":["我家还分有园池，正愿春迟春又归。","风扫花枝犹隐约，日烘云影渐熹微。","客来但欲拚同醉，事往何须叹昨非。","自念生平鱼鸟性，又思川泳与云飞。"]},{"t":"和经仲春日即事 其一","f":"七言律诗","c":["淡烟笼水一溪虚，别有风光在野庐。","幽哢唤人回远梦，落红铺水失清渠。","此生得酒休辞醉，今日何人是奠居。","正向东山念萧索，筠筒烦寄指南车。"]},{"t":"和经仲春日即事 其二","f":"七言律诗","c":["策杖郊原信步行，沙边春水半涵清。","花开旧树香仍在，燕葺破巢功未成。","世路十年尘土面，春风万里鼓鼙声。","从今准拟开怀去，到手荷杯莫厌倾。"]},{"t":"和若夫韵二首 其二","f":"七言律诗","c":["老夫吟咏本非长，僻性年来忽异常。","唯是平生爱风月，致令清夜梦池塘。","正惭遣与非工部，却喜言诗有卜商。","佳句偶从閒里得，片心如到白云乡。"]},{"t":"和若夫韵二首 其一","f":"七言律诗","c":["此身虽缚此心飞，脱得东还似解围。","鹿鹤向人如赞善，林泉见我欲生辉。","食珍他日终难饱，饮水从今亦可肥。","况与亲朋时一醉，益知真乐是来归。"]},{"t":"和范迁善见寄","f":"七言律诗","c":["溪山深处养清高，名位虽穷节行饶。","举世何人堪寂寞，杜门终日自逍遥。","交情已作千金重，别恨空惊一叶飘。","莫向五湖成独往，他年相与到云霄。"]},{"t":"和范迁善见寄三首 其三","f":"五言律诗","c":["新诗劳远寄，深识子怜余。","句法追元白，交情笑耳馀。","飘零疏酒盏，离乱足兵车。","何日相从去，白云深处居。"]},{"t":"和范迁善见寄三首 其二","f":"五言律诗","c":["平生誇志气，妄意语功名。","自顾心无歉，谁知道不行。","霜蹄从暂蹶，嘉木会重荣。","愿守焚舟志，他年学孟明。"]},{"t":"和范迁善见寄三首 其一","f":"五言律诗","c":["苍生未苏息，谁与任安危。","腾蹋思千里，栖迟尚一枝。","谩劳男子志，空忆太平时。","读罢君诗句，愁端愈上眉。"]},{"t":"和范希孟韵","f":"七言律诗","c":["急隐归来趣转深，静中不放一尘侵。","日长宴坐风敲竹，夜久澄心月满林。","诗句每从佳境得，酒杯长为故人斟。","时危莫用计然策，身在五湖空铸金。"]},{"t":"和采石诗韵寄韩无咎","f":"七言律诗","c":["野性从来爱水云，合耕岩下钓溪滨。","宦游愧负平生志，临按欣逢我辈人。","奎阁雄文光照日，锦囊佳句艳争春。","外台况上三年计，一节行看诏墨新。"]},{"t":"和金克孝韵","f":"七言律诗","c":["天公放我作閒人，宠辱无缘到我身。","浊酒兴来宁惜醉，小园日涉不嫌频。","祇知丘壑追元亮，敢望京师说子真。","渐近青春尤可乐，有花如锦草如茵。"]},{"t":"和金克孝韵","f":"七言律诗","c":["长嗟轩冕累吾身，幸得归来见此君。","晚出渔樵呼作伴，行随鹿鹤与同群。","浮光喜踏山前月，弄影贪看水底云。","还有江梅通信息，一枝暗里递清芬。"]},{"t":"和昝通彦早梅韵","f":"七言律诗","c":["岁岁梅花破腊开，赏花尝记坐苍苔。","今年似觉寒犹未，昨夜不知春已回。","喜有暗香供雅客，可无佳句助深杯。","须知不比闲桃李，莫把金刀取次裁。"]},{"t":"和津喜雪二首 其二","f":"七言律诗","c":["我爱平湖绕碧山，山光倒碧到樽前。","同云何事迷千嶂，飞雪俄然蔽一川。","纵使玉楼从地涌，便教银阙与天连。","到头幻化非真实，争似湖山耐岁年。"]},{"t":"和津喜雪二首 其一","f":"七言律诗","c":["六花一夜降中天，飞绕吾庐顿满前。","幻出仙家新窟宅，疑非尘世旧山川。","但惊岩上青松老，不见天边白雁连。","赖有瓮头新酿熟，何妨沉醉度残年。"]},{"t":"和胡宗泽见寄 其二","f":"七言律诗","c":["故人皮里贮阳秋，爱我身如不系舟。","羞向人间为谄首，喜来林下作遨头。","虽无仙骨能骑鹤，尚有閒心可狎鸥。","乘兴惠然时过我，一樽相对笑言稠。"]},{"t":"和胡宗泽见寄 其一","f":"七言律诗","c":["湖边策杖步新晴，陡觉胸襟万虑平。","老去不须防意马，静中已是息心兵。","閒来绿树阴中坐，懒去红尘闹里行。","赖与故人供一醉，不辜今夜月华明。"]},{"t":"和胡经仲即事二首 其二","f":"五言律诗","c":["雨脚转前湾，烟蓑带雨还。","清诗陶野色，薄酒散愁颜。","檐鸟下苔径，溪云媚屋山。","世途方扰扰，谁得似君闲。"]},{"t":"和胡经仲即事二首 其一","f":"五言律诗","c":["世事凭谁论，羁怀只自谙。","风烟悲蜀魄，桑柘老吴蚕。","晚步惜残照，春衫怯晓岚。","日来鼙鼓近，牢落愈无堪。"]},{"t":"和赵观使喜雨","f":"七言律诗","c":["膏泽愆时愧已深，敢期诚意达天垠。","片云忽送千峰雨，一气潜回万壑春。","顿觉老农生喜色，坐令凶岁变佳辰。","忧民虽切功何有，坱圠无私荷大钧。"]},{"t":"和闾丘省干喜雨韵 其二","f":"七言律诗","c":["铃斋坐啸不为颇，愁叹翻然变咏歌。","千里正忧无旧谷，一朝俄喜浃新禾。","云师蔽日如张帜，雨阵横空似拥戈。","我忝郡丞何所补，但将新句对松哦。"]},{"t":"和闾丘省干喜雨韵 其一","f":"七言律诗","c":["良田方苦莠骄骄，甘雨如何閟九霄。","贤守治声喧道路，圣君德泽播黎苗。","宁容赤地炎威炽，果见青天旱气消。","昨夜东皋已沾足，康衢满耳沸歌谣。"]},{"t":"和闾丘莘叟","f":"七言律诗","c":["此时狂敌合灰飞，致我天王下紫微。","士马生风增锐气，旌旗蔽日耀皇威。","愧无一策裨黄屋，滥逐千官扈赭衣。","智略如君宜有用，周行指日看来归。"]},{"t":"和逐年九日阳字韵","f":"七言律诗","c":["天上恩来解郡章，人间那复是重阳。","老身已许归三径，佳节何妨醉百觞。","但有笑容生面目，更无閒事挠心肠。","旁人不信吾归去，今日真成返故乡。"]},{"t":"和郭教授立春除夜之作二首 其二","f":"七言律诗","c":["意广才高困谤伤，又还客里换年光。","驱驰道路风霜苦，放荡江湖日月长。","纵未致身登凤阁，也应平步入鹓行。","胡为尚郁骞腾志，无地栖迟寄寺廊。"]},{"t":"和郭教授立春除夜之作二首 其一","f":"七言律诗","c":["儿童争喜岁时新，老去方知感此辰。","始具杯盘来送腊，又簪幡胜去鞭春。","满斟蕉叶休辞醉，且对桃花痛饮醇。","况有故人能过我，相看岁晚更情亲。"]},{"t":"和钱倅秋晚登帢帻亭","f":"五言律诗","c":["满目悲凉意，凭谁断送秋。","寻僧求竹舍，俯槛得江流。","天末高低雁，波间出没鸥。","时危身局促，却羡汝无愁。"]},{"t":"和陶读山海经十三首韵送机简堂自景星岩再住隐静 其七","f":"五言律诗","c":["扶疏岩下树，入夏总成阴。","几年荆棘地，一旦为丛林。","我方与衲子，共听海潮音。","人生多聚散，离别忽惊心。"]},{"t":"和高簿 其二","f":"七言律诗","c":["家家门外与墙头，叠足排肩看我游。","出郭不应祇独乐，劳农端欲与同忧。","偶逢佳处宁空过，纵迫归时亦暂留。","惭愧高轩远相过，聊持杯酒当茶瓯。"]},{"t":"和高簿 其一","f":"七言律诗","c":["不惮驱驰半驿间，劝耕聊复到禅关。","耳根暗泻潺潺水，眼界横陈叠叠山。","已喜新来春事好，还嗟老去世涂艰。","洪崖幸尔心相契，此后何妨数往还。"]},{"t":"和梁大谏望亭述怀","f":"七言律诗","c":["屡试乘轺与把麾，笑谈自可解重围。","暮年强健人争羡，平日刚方世所稀。","国步尚艰端有赖，君恩方渥未须归。","时清益展经纶手，直上岩廊秉政机。"]},{"t":"和梁次张得酒之作","f":"七言律诗","c":["在处人争馈五浆，风标端是紫微郎。","已能遣兴追工部，更欲消忧对杜康。","阐教暂烦临水泮，趋朝行见裛天香。","老夫素乏惊人句，徒叹辞锋未易当。"]},{"t":"和梁次张韵","f":"七言律诗","c":["妙龄才藻擢文犀，声价何须待品题。","独狍孤衷长拱北，拟摅妙画欲平西。","五年不见心如渴，一笑相逢醉似泥。","我老已为林下计，看君平步上云梯。"]},{"t":"和章德文侍郎题晞浣堂韵寄张法师","f":"七言律诗","c":["丹成人去几经年，怪石峻嶒树曲拳。","超脱每思攀逸驾，沉迷无奈缚尘缘。","胜游徒有骚人咏，绝景难凭妙笔传。","投绂归来应未晚，尚期一访洞中仙。"]},{"t":"和隐老咏梅韵","f":"七言律诗","c":["不惮行行雪满巅，要看与雪斗清妍。","开花虽在三冬杪，结子还居万木先。","水浅横斜聊自见，夜寒幽独有谁怜。","君诗况与梅相亚，传写惭无十样笺。"]},{"t":"和黄作霖董伯玉东山岭上及崇相沙头会饮二首 其二","f":"五言律诗","c":["杖藜寻古寺，把酒俯长流。","节物尚三月，风流似十洲。","且看花满眼，休说锦缠头。","但得陶陶醉，何妨守旧丘。"]},{"t":"和黄作霖董伯玉东山岭上及崇相沙头会饮二首 其一","f":"五言律诗","c":["寒日传佳节，联镳出近坰。","预忧宾骑散，欲驻日车停。","坐上人颓玉，灯前酒尽瓶。","但知修故事，三日不能醒。"]},{"t":"和曾吉甫九日","f":"七言律诗","c":["龙山陈迹已成灰，尚忆当年戏马台。","我幸偶陪黄菊醉，君应亦向白衣来。","风高日朗三秋霁，野旷天清万象开。","好对良辰成乐事，若为不饮竟空回。"]},{"t":"和曾吉甫四明见寄二首 其二","f":"七言律诗","c":["风烟浩荡甬东州，方羡公为烂漫游。","岂料连宵垂雨脚，未容杲日出云头。","扶藜登眺心应在，隐几吟哦趣更幽。","遥想乍晴须痛赏，诗成还肯寄来不。"]},{"t":"和曾吉甫四明见寄二首 其一","f":"七言律诗","c":["老矣何堪剖竹符，频年强出应时须。","腰间谩佩买臣印，月下同游贺老湖。","白雪已知人寡和，清风还忆醉相扶。","十洲三岛登临处，能记稽山病守无。"]},{"t":"和曾吉甫寄韵呈李相之二首 其二","f":"七言律诗","c":["早已相从海上州，朅来鉴水又同游。","驱驰官路俱华发，缱绻交情异白头。","公即横翔层汉去，我将归卧故山幽。","连宵月色如明昼，乘兴还能过我不。"]},{"t":"和曾吉甫寄韵呈李相之二首 其一","f":"七言律诗","c":["千龄景运适相符，况复才华世所须。","腾蹋自应登馆殿，滞留谁谓尚江湖。","从来太瘦缘诗苦，想见闲行信杖扶。","闻道朝来病良愈，高轩还解出门无。"]},{"t":"和紫岩老雪中观梅","f":"七言律诗","c":["清寒池馆静沉沉，惨淡江梅弄晚阴。","雪里有谁能载酒，花前无语自伤心。","低枝似欲迎人笑，清赏何妨倚树吟。","况有争妍佳句在，愈撩诗思不能禁。"]},{"t":"和董伯玉读当涂小集","f":"七言律诗","c":["昔时乘障楚江边，信笔题诗度岁年。","岂敢嘲风仍咏月，祇思问舍与求田。","归心虽似陶元亮，句法宁窥孟浩然。","多谢君诗过褒拂，愈令惭汗出如泉。"]},{"t":"和董伯玉韵","f":"七言律诗","c":["野性耽閒昼掩扉，坐看斜日上书帷。","不妨挟册从吾好，亦学吹竽笑昨痴。","鬓发星星行且老，胸襟碌碌苦亡奇。","与君正欲论心事，又恐分携各一涯。"]},{"t":"和蒋无退怀湖山","f":"七言律诗","c":["多谢君恩许引年，容亲白石与清泉。","不来山下寻诗社，即向湖中棹酒船。","意适更穿花坞去，兴阑还傍竹林眠。","那闻高士飘然句，陡觉身轻似得仙。"]},{"t":"和蒋无退咏雪","f":"七言律诗","c":["腊中三白几年无，今岁呈祥事可书。","披得一蓑方入画，翻成双带又随车。","共惊飞絮迷清昼，更觉同云满太虚。","忆昔读书灯火少，喜穿窗牖映吾庐。"]},{"t":"和蒋宣卿韵 其二","f":"七言律诗","c":["不将有限逐无涯，聊为寻幽驻使华。","千古山川埋剑气，半空台阁雨天花。","终期香火参同社，且赋新诗寄作家。","归晚不须添列炬，预愁惊散暮林鸦。"]},{"t":"和蒋宣卿韵 其一","f":"七言律诗","c":["丐闲章上早知还，卓荦高风岂易攀。","阔步未归龙尾道，胜游先到虎丘山。","千寻古木轩窗外，一缕沉烟几席间。","况是登临有佳客，何妨终夕对孱颜。"]},{"t":"和道叟韵","f":"七言律诗","c":["自怜涉世太迂疏，岂料今朝得自如。","老去不知官况好，归来顿觉道心舒。","湖山深处非凡景，松竹阴中有旧庐。","静坐忽闻乌鹊喜，开门还得故人书。"]},{"t":"和韩子云见寄二首 其二","f":"七言律诗","c":["世态无常似暮霞，人生难久类春花。","已堪入谷携樵斧，还好临湖把钓车。","对酒未能忘酒伴，哦诗尤更忆诗家。","何由会面论心曲，两地相望天一涯。"]},{"t":"和韩子云见寄二首 其一","f":"七言律诗","c":["投绂归来意适然，从今免咏式微篇。","但令晚岁胸中适，安用虚名身后传。","顾我只宜乘载月，如君端合上凌烟。","功成或欲寻真去，莫惜驭风来揖仙。"]},{"t":"和韩子云见寄四首 其四","f":"七言律诗","c":["当时邂逅已心倾，别后逢人问去程。","顾我拙疏非世用，喜君明悟自天成。","十年不见怀芝宇，一笑相逢付曲生。","暂尔就闲宜自爱，上方着意擢豪英。"]},{"t":"和韩子云见寄四首 其三","f":"七言律诗","c":["有花须折酒须倾，少日追欢不计程。","老去自怜心易懒，时过还恐道难成。","城头又是暮云合，江上何时春水生。","早理扁舟归去好，故园犹有万红英。"]},{"t":"和韩子云见寄四首 其二","f":"七言律诗","c":["日在桑榆势欲倾，此时那可更贪程。","屡凭熊轼惭无补，新葺燕巢欣有成。","便好弃官还故里，不妨把酒乐馀生。","经纶事业须公等，看即持荷侍迩英。"]}]};